#[cfg(target_os = "linux")]
#[derive(Debug, Subcommand)]
pub enum WitnessCommands {
    /// Print witness journal entries and receipts.
    Show {
        #[arg(long)]
        journal: PathBuf,
        #[arg(long)]
        journal_id: String,
        #[arg(long, default_value_t = 100)]
        limit: usize,
        #[arg(long)]
        from_sequence: Option<u64>,
        #[arg(long)]
        stage: Option<String>,
    },
    /// Verify witness journal integrity and signatures.
    Verify {
        #[arg(long)]
        journal: PathBuf,
        #[arg(long)]
        trust_bundle: PathBuf,
        #[arg(long)]
        minimum_checkpoint: PathBuf,
        #[arg(long = "checkpoint", required = true)]
        checkpoints: Vec<PathBuf>,
        #[arg(long, default_value_t = 300)]
        max_age_seconds: u64,
    },
    /// Create a signed checkpoint of a witness journal.
    Checkpoint {
        #[arg(long)]
        journal: PathBuf,
        #[arg(long)]
        journal_id: String,
        #[arg(long)]
        artifact: PathBuf,
        #[arg(long)]
        key_dir: Option<PathBuf>,
        #[arg(long)]
        key_name: Option<String>,
        #[arg(long)]
        predecessor: Option<PathBuf>,
        #[arg(long)]
        recover_pending: bool,
    },
    /// Rotate a witness journal signing key with predecessor continuity.
    RotateKey {
        #[arg(long)]
        journal: PathBuf,
        #[arg(long)]
        journal_id: String,
        #[arg(long)]
        artifact: PathBuf,
        #[arg(long)]
        key_dir: PathBuf,
        #[arg(long)]
        old_key: String,
        #[arg(long)]
        new_key: String,
        #[arg(long)]
        predecessor: PathBuf,
    },
    /// Compute a Merkle root from newline-delimited 32-byte record hashes.
    MerkleRoot {
        #[arg(long)]
        leaves: PathBuf,
    },
    /// Verify a serialized inclusion or consistency proof without opening a journal.
    MerkleVerify {
        #[arg(long)]
        proof: PathBuf,
        #[arg(long, default_value = "inclusion", value_parser = validate_merkle_proof_kind)]
        kind: String,
    },
    /// Export a bounded, canonical witness snapshot for independent retention.
    Export {
        #[arg(long)]
        journal: PathBuf,
        #[arg(long)]
        journal_id: String,
        #[arg(long)]
        output: PathBuf,
        #[arg(long, default_value_t = 100_000)]
        max_records: usize,
    },
    /// Verify an exported witness snapshot without opening the live journal.
    VerifyExport {
        #[arg(long)]
        snapshot: PathBuf,
    },
}

