#[derive(Clone, Debug, Subcommand, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ComposeCommands {
    /// Create and start a Compose project.
    Up {
        #[arg(long)]
        profile: Vec<String>,
        /// Build images for services with a build section before starting.
        #[arg(long, default_value_t = false)]
        build: bool,
        /// Return immediately and leave services running. Default is
        /// Docker-compatible attached mode: the command stays alive while
        /// project containers run, which is also the supported mode for
        /// `restart:` supervision in CLI Compose.
        #[arg(short = 'd', long, default_value_t = false)]
        detach: bool,
        /// Limit the operation to these services and their declared dependencies.
        services: Vec<String>,
    },
    /// Watch a Compose project and reconcile drift.
    Watch {
        #[arg(long)]
        profile: Vec<String>,
        #[arg(long, default_value = "2")]
        interval: u64,
    },
    /// Stop a Compose project's services without removing them.
    Stop {
        #[arg(long, default_value_t = 10)]
        timeout: u64,
        services: Vec<String>,
    },
    /// Start previously stopped Compose services.
    Start { services: Vec<String> },
    /// Restart Compose services in dependency order.
    Restart {
        #[arg(long, default_value_t = 10)]
        timeout: u64,
        services: Vec<String>,
    },
    /// Pull images used by Compose services.
    Pull { services: Vec<String> },
    /// Print the parsed, interpolated Compose model as YAML.
    Config,
    /// Stop and remove a Compose project, optionally limited to services.
    Down {
        /// Remove named project volumes as Docker Compose does.
        #[arg(short = 'v', long = "volumes")]
        volumes: bool,
        services: Vec<String>,
    },
    /// List containers of a Compose project.
    Ps,
    /// Read logs of Compose services.
    Logs {
        /// Number of lines to show from the end of each service log.
        #[arg(long)]
        tail: Option<usize>,
        services: Vec<String>,
    },
}

#[derive(Debug, Subcommand)]
