#[cfg(target_os = "linux")]
fn handle_rm(
    runtime: &ContainerRuntime,
    volume_store: &LocalVolumeStore,
    authorization: &SurfaceAuthorization,
    container: &str,
    force: bool,
    volumes: bool,
) -> Result<(), String> {
    if container.trim().is_empty() {
        return Err("rm: container is required".to_string());
    }
    if force && !container_exists(runtime, container)? {
        // Docker treats `rm -f` of a missing container as a successful no-op;
        // without `--force` the missing container is still an error.
        return Ok(());
    }
    let resolved = resolve_container_id(runtime, container)?;
    if force {
        force_kill_running_with_retry(
            || {
                runtime
                    .inspect(&resolved)
                    .map(|record| record.status)
                    .map_err(|err| err.to_string())
            },
            || {
                runtime
                    .kill(&resolved)
                    .map_err(|err| format!("rm: force kill failed: {err}"))
            },
        )?;
    }
    let anonymous_volumes = if volumes {
        let mounted_sources = record_mount_sources(runtime, &resolved)?;
        anonymous_volume_names_for_sources(volume_store, &mounted_sources)?
    } else {
        Vec::new()
    };
    retry_transient_cas(|| {
        runtime
            .remove(&resolved)
            .map_err(|err| format!("rm: container removal failed: {err}"))
    })?;
    let origin = runtime
        .request_origin()
        .ok_or_else(|| "rm: authenticated request origin unavailable".to_string())?;
    for name in anonymous_volumes {
        let permit = authorization
            .authorize_named(
                &origin,
                AuthorizationAction::VolumeDelete,
                ResourceKind::Volume,
                &name,
                1,
            )
            .map_err(|error| error.to_string())?;
        execute_volume_remove(volume_store, &name, permit)?;
    }
    println!("rm: {resolved}");
    Ok(())
}

#[cfg(target_os = "linux")]
fn record_mount_sources(runtime: &ContainerRuntime, id: &str) -> Result<Vec<String>, String> {
    Ok(runtime
        .inspect(id)
        .map_err(|error| error.to_string())?
        .mounts
        .into_iter()
        .map(|mount| mount.source)
        .collect())
}

#[cfg(target_os = "linux")]
fn anonymous_volume_names_for_sources(
    volume_store: &LocalVolumeStore,
    mounted_sources: &[String],
) -> Result<Vec<String>, String> {
    Ok(volume_store
        .list()
        .map_err(|error| error.to_string())?
        .into_iter()
        .filter(|volume| {
            mounted_sources.iter().any(|source| source == &volume.path)
                && volume.driver_opts.get("ferrocrate.anonymous") == Some(&"true".to_string())
        })
        .map(|volume| volume.name)
        .collect())
}

