fn reset_network_kernel_effect_count() {
    self::network_lifecycle::reset_network_kernel_effect_count();
}

#[cfg(test)]
fn network_kernel_effect_count() -> u32 {
    self::network_lifecycle::network_kernel_effect_count()
}

fn create_network_record(
    name: &str,
    subnet: Option<&str>,
    gateway: Option<&str>,
    ipv6_subnet: Option<&str>,
    ipv6_gateway: Option<&str>,
) -> Result<NetworkRecord, String> {
    validate_network_name(name)?;
    let subnet = subnet.unwrap_or("172.20.0.0/16");
    let (subnet_ip, prefix) = parse_ipv4_cidr(subnet)?;
    let network_ip = subnet_network_addr(subnet_ip, prefix);
    let gateway_ip = match gateway {
        Some(value) => value
            .parse::<Ipv4Addr>()
            .map_err(|_| format!("network: invalid gateway {value}"))?,
        None => default_gateway_for_subnet(network_ip),
    };
    if !ip_in_subnet(gateway_ip, network_ip, prefix) {
        return Err(format!(
            "network: gateway {gateway_ip} is outside subnet {network_ip}/{prefix}"
        ));
    }
    let ipv6_cidr = match ipv6_subnet {
        Some(value) => {
            let (addr, prefix) = parse_ipv6_cidr(value)?;
            let gateway = match ipv6_gateway {
                Some(gateway) => gateway
                    .parse::<std::net::Ipv6Addr>()
                    .map_err(|_| format!("network: invalid IPv6 gateway {gateway}"))?,
                None => default_ipv6_gateway(addr, prefix),
            };
            if !ipv6_in_subnet(gateway, addr, prefix) {
                return Err(format!(
                    "network: IPv6 gateway {gateway} is outside subnet {addr}/{prefix}"
                ));
            }
            Some(format!("{gateway}/{prefix}"))
        }
        None if ipv6_gateway.is_some() => {
            return Err("network: --ipv6-gateway requires --ipv6-subnet".into())
        }
        None => None,
    };
    Ok(NetworkRecord {
        name: name.to_string(),
        driver: "bridge".to_string(),
        subnet: format!("{network_ip}/{prefix}"),
        gateway: gateway_ip.to_string(),
        bridge_name: bridge_name_for_network(name),
        bridge_cidr: format!("{gateway_ip}/{prefix}"),
        ipv6_cidr,
        labels: BTreeMap::new(),
        created_at_unix: std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs())
            .unwrap_or(0),
        generation: 1,
    })
}

struct RunNetworkBinding {
    mode: String,
    association: Option<String>,
    bridge_cidr: Option<String>,
    bridge_name: Option<String>,
}

#[cfg(test)]
fn bind_run_network(
    runtime_dir: &Path,
    network: &str,
    bridge_cidr: Option<&str>,
    bridge_name: Option<&str>,
) -> Result<RunNetworkBinding, String> {
    bind_run_network_inner(runtime_dir, None, network, bridge_cidr, bridge_name)
}

#[cfg(target_os = "linux")]
fn bind_run_network_for_runtime(
    runtime_dir: &Path,
    runtime: &ContainerRuntime,
    network: &str,
    bridge_cidr: Option<&str>,
    bridge_name: Option<&str>,
) -> Result<RunNetworkBinding, String> {
    bind_run_network_inner(runtime_dir, Some(runtime), network, bridge_cidr, bridge_name)
}

fn bind_run_network_inner(
    runtime_dir: &Path,
    runtime: Option<&ContainerRuntime>,
    network: &str,
    bridge_cidr: Option<&str>,
    bridge_name: Option<&str>,
) -> Result<RunNetworkBinding, String> {
    let mut mode = network.to_string();
    if mode == "encrypted" {
        mode = "wireguard".to_string();
    }
    let mut resolved_bridge_cidr = bridge_cidr.map(|value| value.to_string());
    let mut resolved_bridge_name = bridge_name.map(|value| value.to_string());
    let association = if let Some(managed) = mode.strip_prefix("managed:") {
        ferro_core::managed_overlay::ManagedOverlayRef::parse(&mode)
            .map_err(|error| format!("run: invalid managed overlay: {error}"))?;
        Some(managed.to_string())
    } else if let Some(pid) = mode.strip_prefix("container:") {
        let pid = pid.strip_prefix("pid:").ok_or_else(|| {
            "run: container network binding must use container:pid:<leader-pid>".to_string()
        })?;
        let pid = pid
            .parse::<u32>()
            .map_err(|_| "run: container network binding leader PID is invalid".to_string())?;
        if pid == 0 {
            return Err("run: container network binding leader PID must be non-zero".to_string());
        }
        mode = format!("container:pid:{pid}");
        None
    } else if is_builtin_network_mode(&mode) {
        validate_network_mode(&mode)?;
        Some(mode.clone())
    } else {
        let named = resolve_named_network(runtime_dir, network)?;
        // A rootless slirp4netns namespace is owned by the first running
        // container on a named network. Join it for later members, matching
        // the Compose rootless network path without requiring a host bridge.
        let records = runtime.and_then(|runtime| runtime.list().ok()).unwrap_or_default();
        mode = rootless_named_network_mode(
            nix::unistd::Uid::effective().is_root(),
            &records,
            &named.name,
        )
        .unwrap_or_else(|| "bridge".to_string());
        if resolved_bridge_cidr.is_none() {
            resolved_bridge_cidr = Some(named.bridge_cidr.clone());
        }
        if resolved_bridge_name.is_none() {
            resolved_bridge_name = Some(named.bridge_name.clone());
        }
        Some(named.name)
    };
    Ok(RunNetworkBinding {
        mode,
        association,
        bridge_cidr: resolved_bridge_cidr,
        bridge_name: resolved_bridge_name,
    })
}

#[cfg(target_os = "linux")]
fn rootless_named_network_mode(
    is_root: bool,
    records: &[ferro_core::container_store::ContainerRecord],
    network_name: &str,
) -> Option<String> {
    (!is_root).then(|| {
        records.iter().find(|record| {
            record.status == "running"
                && record
                    .effective_network_endpoints()
                    .iter()
                    .any(|endpoint| endpoint.network_name == network_name)
        })
    })
    .flatten()
    .map(|record| format!("container:pid:{}", record.pid))
}

fn resolve_named_network(runtime_dir: &Path, name: &str) -> Result<NetworkRecord, String> {
    let records = load_networks(runtime_dir)?;
    records
        .into_iter()
        .find(|record| record.name == name)
        .ok_or_else(|| format!("network: not found {name}"))
}

fn docker_named_endpoint_config(
    runtime_dir: &Path,
    name: &str,
) -> Result<ferro_core::runtime::NamedNetworkEndpointConfig, String> {
    if name == "bridge" {
        let cidr = std::env::var("FERROCRATE_BRIDGE_CIDR")
            .unwrap_or_else(|_| "10.0.0.1/24".to_string());
        let (gateway, prefix) = parse_ipv4_cidr(&cidr)?;
        let subnet = subnet_network_addr(gateway, prefix);
        return Ok(ferro_core::runtime::NamedNetworkEndpointConfig {
            network_name: "bridge".to_string(),
            generation: 1,
            bridge_name: std::env::var("FERROCRATE_BRIDGE_NAME")
                .unwrap_or_else(|_| "ferro0".to_string()),
            ipv4_subnet: format!("{subnet}/{prefix}"),
            ipv4_gateway: gateway.to_string(),
            ipv6_gateway_cidr: std::env::var("FERROCRATE_BRIDGE_IPV6_CIDR").ok(),
            aliases: Vec::new(),
        });
    }
    let record = resolve_named_network(runtime_dir, name)?;
    Ok(ferro_core::runtime::NamedNetworkEndpointConfig {
        network_name: record.name,
        generation: record.generation,
        bridge_name: record.bridge_name,
        ipv4_subnet: record.subnet,
        ipv4_gateway: record.gateway,
        ipv6_gateway_cidr: record.ipv6_cidr,
        aliases: Vec::new(),
    })
}

#[cfg(target_os = "linux")]
fn handle_network(
    runtime_dir: &Path,
    runtime: &ContainerRuntime,
    command: NetworkCommands,
    authorization: &SurfaceAuthorization,
) -> Result<(), String> {
    let origin = RequestOrigin::cli_current().map_err(|error| error.to_string())?;
    handle_network_authorized(runtime_dir, runtime, command, &origin, authorization)
}

#[cfg(target_os = "linux")]
fn handle_network_authorized(
    runtime_dir: &Path,
    runtime: &ContainerRuntime,
    command: NetworkCommands,
    origin: &RequestOrigin,
    authorization: &SurfaceAuthorization,
) -> Result<(), String> {
    let recovery = self::network_lifecycle::recover_network_lifecycles(
        runtime_dir,
        cli_network_kernel().as_ref(),
    )
    .map_err(|error| format!("network recovery failed: {error}"))?;
    if let Some(entry) = recovery.entries.iter().find(|entry| {
        matches!(
            entry.verdict,
            self::network_lifecycle::NetworkRecoveryVerdict::Quarantined
        )
    }) {
        return Err(format!(
            "network recovery quarantined {}: {}",
            entry.network,
            entry.detail.as_deref().unwrap_or("no detail")
        ));
    }

    match command {
        NetworkCommands::Create {
            name,
            subnet,
            gateway,
            ipv6_subnet,
            ipv6_gateway,
            labels,
        } => {
            if is_builtin_network_mode(&name) {
                return Err(format!("network: reserved name {name}"));
            }
            let records = load_networks(runtime_dir)?;
            if records.iter().any(|record| record.name == name) {
                return Err(format!("network: already exists {name}"));
            }
            let mut record = create_network_record(
                &name,
                subnet.as_deref(),
                gateway.as_deref(),
                ipv6_subnet.as_deref(),
                ipv6_gateway.as_deref(),
            )?;
            record.labels = parse_key_values("network: label", &labels)?
                .into_iter()
                .collect();
            if records.iter().any(|existing| {
                existing.bridge_name == record.bridge_name && existing.name != record.name
            }) {
                return Err(format!(
                    "network: bridge name collision {}",
                    record.bridge_name
                ));
            }
            let proof = authorization
                .authorize_named(
                    origin,
                    AuthorizationAction::NetworkCreate,
                    ResourceKind::Network,
                    &name,
                    record.generation,
                )
                .map_err(|error| error.to_string())?;
            if nix::unistd::Uid::effective().is_root()
                || self::network_lifecycle::FileBackedNetworkKernel::from_env().is_some()
                || cfg!(test)
            {
                execute_network_create(runtime_dir, &record, proof)?;
            } else {
                // Rootless named networks are user-space slirp namespaces;
                // publishing the record makes the first member the leader.
                save_networks(runtime_dir, &records.iter().cloned().chain(std::iter::once(record.clone())).collect::<Vec<_>>())?;
                proof.finish(true).map_err(|error| error.to_string())?;
            }
            println!(
                "network create: name={} driver={} subnet={} gateway={}",
                record.name, record.driver, record.subnet, record.gateway
            );
        }
        NetworkCommands::Ls { filters, format } => {
            let filters = parse_cli_filters(&filters)?;
            validate_docker_network_filters(&filters)?;
            let records = load_networks(runtime_dir)?
                .into_iter()
                .filter(|record| {
                    docker_network_matches_filters(
                        &DockerNetworkView {
                            name: &record.name,
                            driver: &record.driver,
                            labels: &record.labels,
                        },
                        &filters,
                    )
                })
                .collect::<Vec<_>>();
            let include_bridge = docker_network_matches_filters(
                &DockerNetworkView {
                    name: "bridge",
                    driver: "bridge",
                    labels: &BTreeMap::new(),
                },
                &filters,
            );
            if format == "json" {
                let mut entries = Vec::new();
                if include_bridge {
                    entries.push(serde_json::json!({
                        "Name": "bridge",
                        "Id": "bridge",
                        "Driver": "bridge",
                        "Scope": "local",
                        "IPAM": {"Config": [{
                            "Subnet": "10.0.0.0/24",
                            "Gateway": "10.0.0.1"
                        }]},
                    }));
                }
                entries.extend(records.into_iter().map(|record| {
                    let ipv6_config = docker_network_ipv6_config(&record);
                    let mut ipam_config = vec![serde_json::json!({
                        "Subnet": record.subnet,
                        "Gateway": record.gateway,
                    })];
                    if let Some(config) = ipv6_config {
                        ipam_config.push(config);
                    }
                    serde_json::json!({
                        "Name": record.name,
                        "Id": record.name,
                        "Driver": record.driver,
                        "Scope": "local",
                        "IPAM": {"Config": ipam_config},
                    })
                }));
                println!(
                    "{}",
                    serde_json::to_string_pretty(&entries).map_err(|error| error.to_string())?
                );
                return Ok(());
            }
            println!("NAME\tDRIVER\tSUBNET\tGATEWAY");
            if include_bridge {
                println!("bridge\tbridge\t10.0.0.0/24\t10.0.0.1");
            }
            for record in records {
                println!(
                    "{}\t{}\t{}\t{}",
                    record.name, record.driver, record.subnet, record.gateway
                );
            }
        }
        NetworkCommands::Inspect { name, format } => {
            let payload = if name == "bridge" {
                let containers = docker_network_containers(runtime, "bridge")?;
                serde_json::json!({
                    "Name": "bridge", "Id": "bridge", "Driver": "bridge",
                    "Scope": "local", "IPAM": {"Config": []}, "Containers": containers
                })
            } else {
                let record = load_networks(runtime_dir)?
                    .into_iter()
                    .find(|record| record.name == name)
                    .ok_or_else(|| format!("network: not found {name}"))?;
                let containers = docker_network_containers(runtime, &record.name)?;
                let ipv6_config = docker_network_ipv6_config(&record);
                let mut ipam_config = vec![serde_json::json!({
                    "Subnet": record.subnet,
                    "Gateway": record.gateway
                })];
                if let Some(config) = ipv6_config {
                    ipam_config.push(config);
                }
                serde_json::json!({
                    "Name": record.name, "Id": record.name, "Driver": record.driver,
                    "Scope": "local", "EnableIPv6": record.ipv6_cidr.is_some(),
                    "IPAM": {"Config": ipam_config}, "Containers": containers
                })
            };
            if format == "json" {
                println!(
                    "{}",
                    serde_json::to_string_pretty(&payload).map_err(|error| error.to_string())?
                );
            } else {
                println!("Name: {}", payload["Name"]);
                println!("Driver: {}", payload["Driver"]);
                println!("Scope: {}", payload["Scope"]);
            }
        }
        NetworkCommands::Rm { name } => {
            if is_builtin_network_mode(&name) {
                return Err(format!("network: cannot remove builtin network {name}"));
            }
            let associations = runtime.list().map_err(|err| err.to_string())?;
            let records = load_networks(runtime_dir)?;
            let stored = records
                .iter()
                .find(|record| record.name == name)
                .ok_or_else(|| format!("network: not found {name}"))?
                .clone();
            let proof = authorization
                .authorize_named(
                    origin,
                    AuthorizationAction::NetworkDelete,
                    ResourceKind::Network,
                    &name,
                    stored.generation,
                )
                .map_err(|error| error.to_string())?;
            if nix::unistd::Uid::effective().is_root()
                || self::network_lifecycle::FileBackedNetworkKernel::from_env().is_some()
                || cfg!(test)
            {
                execute_network_remove(runtime_dir, &stored, &associations, proof)?;
            } else {
                let remaining = records.into_iter().filter(|record| record.name != name).collect::<Vec<_>>();
                save_networks(runtime_dir, &remaining)?;
                proof.finish(true).map_err(|error| error.to_string())?;
            }
            println!("network rm: {name}");
        }
        NetworkCommands::Connect {
            network,
            container,
            aliases,
        } => {
            let id = resolve_container_id(runtime, &container)?;
            let mut config = docker_named_endpoint_config(runtime_dir, &network)?;
            config.aliases = aliases;
            let permit = authorization
                .authorize_named(
                    origin,
                    AuthorizationAction::NetworkAttach,
                    ResourceKind::Network,
                    &config.network_name,
                    config.generation,
                )
                .map_err(|error| error.to_string())?;
            match runtime.connect_network(&id, config) {
                Ok(()) => permit.finish(true).map_err(|error| error.to_string())?,
                Err(error) => {
                    if matches!(
                        error,
                        ferro_core::runtime::RuntimeError::PostEffectPersistence(_)
                    ) {
                        permit.finish_unknown().map_err(|finish| finish.to_string())?;
                    } else {
                        permit.finish(false).map_err(|finish| finish.to_string())?;
                    }
                    return Err(error.to_string());
                }
            }
        }
        NetworkCommands::Disconnect {
            network,
            container,
            force,
        } => {
            let id = resolve_container_id(runtime, &container)?;
            let config = docker_named_endpoint_config(runtime_dir, &network)?;
            let permit = authorization
                .authorize_named(
                    origin,
                    AuthorizationAction::NetworkDetach,
                    ResourceKind::Network,
                    &config.network_name,
                    config.generation,
                )
                .map_err(|error| error.to_string())?;
            match runtime.disconnect_network(&id, &config.network_name) {
                Ok(()) => permit.finish(true).map_err(|error| error.to_string())?,
                Err(error) if force && error.to_string().contains("not connected") => {
                    permit.finish(true).map_err(|finish| finish.to_string())?;
                }
                Err(error) => {
                    if matches!(
                        error,
                        ferro_core::runtime::RuntimeError::PostEffectPersistence(_)
                    ) {
                        permit.finish_unknown().map_err(|finish| finish.to_string())?;
                    } else {
                        permit.finish(false).map_err(|finish| finish.to_string())?;
                    }
                    return Err(error.to_string());
                }
            }
        }
        NetworkCommands::Prune { filters } => {
            let filters = parse_cli_filters(&filters)?;
            validate_docker_network_filters(&filters)?;
            let associations = runtime.list().map_err(|err| err.to_string())?;
            let records = load_networks(runtime_dir)?;
            let mut deleted = Vec::new();
            for record in records.into_iter().filter(|record| {
                !is_builtin_network_mode(&record.name)
                    && docker_network_matches_filters(
                        &DockerNetworkView {
                            name: &record.name,
                            driver: &record.driver,
                            labels: &record.labels,
                        },
                        &filters,
                    )
                    && !associations.iter().any(|container| {
                        container
                            .effective_network_endpoints()
                            .iter()
                            .any(|endpoint| endpoint.network_name == record.name)
                    })
            }) {
                let proof = authorization
                    .authorize_named(
                        origin,
                        AuthorizationAction::NetworkDelete,
                        ResourceKind::Network,
                        &record.name,
                        record.generation,
                    )
                    .map_err(|error| error.to_string())?;
                if nix::unistd::Uid::effective().is_root()
                    || self::network_lifecycle::FileBackedNetworkKernel::from_env().is_some()
                    || cfg!(test)
                {
                    execute_network_remove(runtime_dir, &record, &associations, proof)?;
                } else {
                    let remaining = load_networks(runtime_dir)?
                        .into_iter()
                        .filter(|candidate| candidate.name != record.name)
                        .collect::<Vec<_>>();
                    save_networks(runtime_dir, &remaining)?;
                    proof.finish(true).map_err(|error| error.to_string())?;
                }
                deleted.push(record.name);
            }
            println!("network prune: removed={}", deleted.len());
        }
    }
    Ok(())
}

fn cli_network_kernel() -> Box<dyn self::network_lifecycle::NetworkKernel> {
    // Explicit opt-in for the file-backed emulator (Docker/CLI harnesses).
    // Default production path remains SystemBridgeKernel.
    if let Some(kernel) = self::network_lifecycle::FileBackedNetworkKernel::from_env() {
        return Box::new(kernel);
    }
    #[cfg(test)]
    {
        Box::new(CliKernelProxy)
    }
    #[cfg(not(test))]
    {
        Box::new(self::network_lifecycle::SystemBridgeKernel)
    }
}

#[cfg(test)]
struct CliKernelProxy;

#[cfg(test)]
impl self::network_lifecycle::NetworkKernel for CliKernelProxy {
    fn create_bridge(
        &self,
        config: &ferro_net::BridgeConfig,
    ) -> Result<(), self::network_lifecycle::NetworkKernelError> {
        self::network_lifecycle::CliTestKernel::with_current(|kernel| kernel.create_bridge(config))
    }

    fn destroy_bridge(
        &self,
        identity: &self::network_lifecycle::BridgeIdentity,
    ) -> Result<(), self::network_lifecycle::NetworkKernelError> {
        self::network_lifecycle::CliTestKernel::with_current(|kernel| {
            kernel.destroy_bridge(identity)
        })
    }

    fn observe_bridge(
        &self,
        name: &str,
    ) -> Result<
        Option<self::network_lifecycle::BridgeIdentity>,
        self::network_lifecycle::NetworkKernelError,
    > {
        self::network_lifecycle::CliTestKernel::with_current(|kernel| kernel.observe_bridge(name))
    }
}

fn execute_network_create(
    runtime_dir: &Path,
    record: &NetworkRecord,
    permit: SurfacePermit,
) -> Result<(), String> {
    let create =
        NetworkCreateRecord::from_record(record.clone()).map_err(|error| error.to_string())?;
    self::network_lifecycle::create_authorized(
        runtime_dir,
        &create,
        permit,
        cli_network_kernel().as_ref(),
    )
    .map(|_| ())
    .map_err(|error| error.to_string())
}

fn execute_network_remove(
    runtime_dir: &Path,
    record: &NetworkRecord,
    associations: &[ferro_core::container_store::ContainerRecord],
    permit: SurfacePermit,
) -> Result<(), String> {
    // Exact BridgeIdentity deletion authority requires the last StoreCommitted
    // observed identity. Synthesizing from the store record (ifindex: None)
    // would allow an inexact or absent-bridge path to unpublish without that
    // authority; fail closed before delete, unpublish, or any kernel effect.
    let expected = match last_committed_bridge_identity(runtime_dir, &record.name)
        .map_err(|error| error.to_string())?
    {
        Some(identity) => identity,
        None => {
            permit.finish(false).map_err(|error| error.to_string())?;
            return Err(format!(
                "network: missing committed bridge identity for {}",
                record.name
            ));
        }
    };
    self::network_lifecycle::delete_authorized(
        runtime_dir,
        &record.name,
        &expected,
        associations,
        record.generation,
        permit,
        cli_network_kernel().as_ref(),
    )
    .map_err(|error| error.to_string())
}

fn parse_driver_opts(opts: &[String]) -> Result<BTreeMap<String, String>, String> {
    let mut out = BTreeMap::new();
    for entry in opts {
        let mut parts = entry.splitn(2, '=');
        let key = parts.next().unwrap_or("").trim();
        let value = parts.next().unwrap_or("").trim();
        if key.is_empty() || value.is_empty() {
            return Err("volume: opt must be key=value".to_string());
        }
        out.insert(key.to_string(), value.to_string());
    }
    Ok(out)
}

fn parse_env_entries(envs: &[String]) -> Result<Vec<String>, String> {
    for entry in envs {
        let mut parts = entry.splitn(2, '=');
        let key = parts.next().unwrap_or("").trim();
        let value = parts.next();
        if key.is_empty() || value.is_none() {
            return Err("run: env must be KEY=VALUE".to_string());
        }
    }
    Ok(envs.to_vec())
}

fn parse_key_values(kind: &str, entries: &[String]) -> Result<HashMap<String, String>, String> {
    let mut out = HashMap::new();
    for entry in entries {
        let mut parts = entry.splitn(2, '=');
        let key = parts.next().unwrap_or("").trim();
        let value = parts.next().unwrap_or("").trim();
        // Docker permits empty label values (`--label key` and `key=`), and
        // compose relies on it for labels like project.environment_file.
        if key.is_empty() {
            return Err(format!("{kind}: must be key=value"));
        }
        out.insert(key.to_string(), value.to_string());
    }
    Ok(out)
}

fn build_health_config(
    health_cmd: Option<&str>,
    health_interval: Option<u64>,
    health_timeout: Option<u64>,
    health_retries: Option<u32>,
    health_start_period: Option<u64>,
) -> Result<Option<ferro_core::container_store::HealthConfig>, String> {
    let has_overrides = health_interval.is_some()
        || health_timeout.is_some()
        || health_retries.is_some()
        || health_start_period.is_some();
    let Some(cmd) = health_cmd else {
        if has_overrides {
            return Err("run: health-cmd is required when health options are set".to_string());
        }
        return Ok(None);
    };
    if cmd.trim().is_empty() {
        return Err("run: health-cmd must not be empty".to_string());
    }
    Ok(Some(ferro_core::container_store::HealthConfig {
        cmd: vec!["/bin/sh".to_string(), "-c".to_string(), cmd.to_string()],
        interval_secs: health_interval.unwrap_or(30),
        timeout_secs: health_timeout.unwrap_or(5),
        retries: health_retries.unwrap_or(3),
        start_period_secs: health_start_period.unwrap_or(0),
    }))
}

fn effective_readonly(profile: &str, read_only: bool, read_write: bool) -> Result<bool, String> {
    if read_only && read_write {
        return Err("run: cannot set both --read-only and --read-write".to_string());
    }
    if read_only {
        return Ok(true);
    }
    if read_write {
        return Ok(false);
    }
    match profile {
        "prod" => Ok(true),
        "dev" => Ok(false),
        _ => Err("run: profile must be dev|prod".to_string()),
    }
}

fn parse_restart_policy(
    policy: &str,
) -> Result<ferro_core::container_store::RestartPolicy, String> {
    if let Some(limit) = policy.strip_prefix("on-failure:") {
        let limit = limit
            .parse::<u32>()
            .map_err(|_| "run: on-failure retry count must be a non-negative integer".to_string())?;
        return Ok(if limit == 0 {
            ferro_core::container_store::RestartPolicy::OnFailure
        } else {
            ferro_core::container_store::RestartPolicy::OnFailureWithRetries(limit)
        });
    }
    match policy {
        "no" => Ok(ferro_core::container_store::RestartPolicy::No),
        "on-failure" => Ok(ferro_core::container_store::RestartPolicy::OnFailure),
        "always" => Ok(ferro_core::container_store::RestartPolicy::Always),
        "unless-stopped" => Ok(ferro_core::container_store::RestartPolicy::UnlessStopped),
        _ => Err(
            "run: restart must be no|on-failure[:N]|always|unless-stopped".to_string(),
        ),
    }
}

#[cfg(target_os = "linux")]
fn parse_capabilities(entries: &[String]) -> Result<Vec<caps::Capability>, String> {
    let mut out = Vec::new();
    for entry in entries {
        let trimmed = entry.trim();
        if trimmed.is_empty() {
            return Err("run: cap-add must not be empty".to_string());
        }
        let normalized = if trimmed.starts_with("CAP_") {
            trimmed.to_string()
        } else {
            format!("CAP_{}", trimmed)
        };
        let cap = normalized
            .parse::<caps::Capability>()
            .map_err(|_| format!("run: unknown capability {trimmed}"))?;
        out.push(cap);
    }
    Ok(out)
}

#[cfg(target_os = "linux")]
// Docker exec's stream and process options are independent CLI protocol fields.
#[allow(clippy::too_many_arguments)]
fn handle_exec(
    runtime: &ContainerRuntime,
    container: &str,
    cmd: &[String],
    env: &[String],
    user: Option<&str>,
    workdir: Option<&str>,
    interactive: bool,
    tty: bool,
) -> Result<(), String> {
    if container.trim().is_empty() {
        return Err("exec: container is required".to_string());
    }
    if cmd.is_empty() {
        return Err("exec: command is required".to_string());
    }
    let resolved = resolve_container_id(runtime, container)?;
    require_live_container(runtime, &resolved)?;
    if runtime
        .inspect(&resolved)
        .map_err(|err| format!("container {resolved} lookup failed: {err}"))?
        .status
        == "paused"
    {
        return Err(format!(
            "container {resolved} is paused, unpause the container before exec"
        ));
    }
    let result = if interactive {
        let mut input = Vec::new();
        std::io::stdin()
            .take(4 * 1024 * 1024 + 1)
            .read_to_end(&mut input)
            .map_err(|error| format!("exec: read stdin failed: {error}"))?;
        if input.len() > 4 * 1024 * 1024 {
            return Err("exec: stdin exceeds 4 MiB".to_string());
        }
        if !env.is_empty() || user.is_some() || workdir.is_some() {
            return Err("exec: interactive environment, user, and working-directory overrides are unsupported".to_string());
        }
        runtime.exec_with_input(&resolved, cmd, &input, tty)
    } else {
        runtime.exec_with_options(
            &resolved,
            cmd,
            &ferro_core::runtime::ExecOptions {
                env: env.to_vec(),
                user: user.map(ToOwned::to_owned),
                working_dir: workdir.map(ToOwned::to_owned),
                tty,
            },
        )
    }
    .map_err(|err| err.to_string())?;
    if !result.stdout.is_empty() {
        print!("{}", result.stdout);
    }
    if !result.stderr.is_empty() {
        eprint!("{}", result.stderr);
    }
    Ok(())
}

/// Docker rejects the `kill`, `top` and `exec` commands against a container
/// whose state is not live, while the local runtime tolerates terminal states
/// for race recovery. The CLI enforces Docker's contract here.
fn require_live_container(runtime: &ContainerRuntime, resolved: &str) -> Result<(), String> {
    let status = runtime
        .inspect(resolved)
        .map_err(|err| format!("container {resolved} lookup failed: {err}"))?
        .status;
    if matches!(status.as_str(), "running" | "paused" | "restarting") {
        return Ok(());
    }
    Err(format!("container {resolved} is not running"))
}

#[cfg(target_os = "linux")]
/// Whether a container name or id prefix currently resolves to a record.
/// Used by `rm -f`, which must treat an absent container as already removed.
fn container_exists(runtime: &ContainerRuntime, container: &str) -> Result<bool, String> {
    if runtime.inspect(container).is_ok() {
        return Ok(true);
    }
    Ok(runtime
        .list()
        .map_err(|err| err.to_string())?
        .into_iter()
        .any(|record| {
            record.id.starts_with(container) || record.name.as_deref() == Some(container)
        }))
}

fn resolve_container_id(runtime: &ContainerRuntime, container: &str) -> Result<String, String> {
    if runtime.inspect(container).is_ok() {
        return Ok(container.to_string());
    }
    let records = runtime.list().map_err(|err| err.to_string())?;
    let matches = records
        .into_iter()
        .filter(|record| {
            record.id.starts_with(container) || record.name.as_deref() == Some(container)
        })
        .map(|record| record.id)
        .collect::<Vec<_>>();
    match matches.len() {
        0 => Err(format!("container not found: {container}")),
        1 => Ok(matches.into_iter().next().unwrap()),
        _ => Err(format!("container name is not unique: {container}")),
    }
}

fn handle_pull(
    store: &LocalImageStore,
    image: &str,
    lazy: bool,
    authorization: &SurfaceAuthorization,
) -> Result<(), String> {
    let origin = RequestOrigin::cli_current().map_err(|error| error.to_string())?;
    handle_pull_authorized(store, image, lazy, &origin, authorization)
}

fn handle_pull_authorized(
    store: &LocalImageStore,
    image: &str,
    lazy: bool,
    origin: &RequestOrigin,
    authorization: &SurfaceAuthorization,
) -> Result<(), String> {
    let binding =
        ferro_core::image_fetch::inspect_image_binding(image).map_err(|error| error.to_string())?;
    let proof = authorization
        .authorize_image_fetch_plan(origin, &binding, 1)
        .map_err(|error| error.to_string())?;
    execute_image_pull(store, lazy, binding, proof)
}

/// Docker image operations use newline-delimited JSON progress records.  Keep
/// the synthetic records here until registry transfers expose byte callbacks;
/// consumers can already render them exactly like normal layer progress.
fn docker_image_progress(reference: &str, terminal_status: &str) -> Vec<u8> {
    [
        serde_json::json!({
            "status": "Downloading",
            "id": reference,
            "progressDetail": { "current": 0, "total": 1 },
        }),
        serde_json::json!({
            "status": "Extracting",
            "id": reference,
            "progressDetail": { "current": 1, "total": 1 },
        }),
        serde_json::json!({
            "status": terminal_status,
            "id": reference,
            "progressDetail": { "current": 1, "total": 1 },
        }),
    ]
    .into_iter()
    .map(|frame| format!("{frame}\n"))
    .collect::<String>()
    .into_bytes()
}

fn docker_pull_status(reference: &str, lazy: bool) -> Vec<u8> {
    docker_image_progress(
        reference,
        if lazy { "Manifest fetched" } else { "Pull complete" },
    )
}

fn print_docker_image_progress(body: &[u8]) -> Result<(), String> {
    for line in std::str::from_utf8(body)
        .map_err(|error| format!("docker progress is not UTF-8: {error}"))?
        .lines()
    {
        let frame: serde_json::Value = serde_json::from_str(line)
            .map_err(|error| format!("docker progress frame is invalid JSON: {error}"))?;
        let status = frame["status"]
            .as_str()
            .ok_or_else(|| "docker progress frame has no status".to_string())?;
        let id = frame["id"].as_str().unwrap_or_default();
        let detail = &frame["progressDetail"];
        match (detail["current"].as_u64(), detail["total"].as_u64()) {
            (Some(current), Some(total)) => println!("{id}: {status} {current}/{total}"),
            _ => println!("{id}: {status}"),
        }
    }
    Ok(())
}

fn execute_image_pull(
    store: &LocalImageStore,
    lazy: bool,
    plan: ferro_core::image_fetch::ImageFetchPlan,
    permit: SurfacePermit,
) -> Result<(), String> {
    if lazy {
        let runtime_dir = runtime_dir();
        let canonical = ferro_core::image_fetch::pull_manifest_only_with_store_authorized(
            &runtime_dir,
            &plan,
            store,
            permit,
        )
        .map_err(|err| err.to_string())?;
        println!("pull: manifest-only image={canonical}");
        return Ok(());
    }
    let runtime_dir = runtime_dir();
    eprintln!("pull: fetching image={}", plan.canonical_reference());
    ferro_core::image_fetch::pull_image_with_store_authorized(&runtime_dir, &plan, store, permit)
        .map_err(|error| error.to_string())?;
    eprintln!("pull: image={}", plan.canonical_reference());
    Ok(())
}

fn handle_push(store: &LocalImageStore, image: &str) -> Result<(), String> {
    parse_image_reference(image).map_err(|err| err.to_string())?;
    let canonical = canonicalize_reference(image).map_err(|err| err.to_string())?;
    let record = resolve_reference(store, &canonical)
        .map_err(|err| err.to_string())?
        .ok_or_else(|| format!("push: image not found: {canonical}"))?;

    let client = RegistryClient::new().map_err(|err| err.to_string())?;
    let auth = resolve_registry_auth(&canonical).map_err(|err| err.to_string())?;
    let runtime_dir = runtime_dir();
    let layer_paths =
        ferro_core::image_fetch::resolve_layer_paths_with_store(&runtime_dir, &canonical, store)
            .map_err(|err| err.to_string())?;
    let config_path =
        ferro_core::image_fetch::resolve_config_path_with_store(&runtime_dir, &canonical, store)
            .map_err(|err| err.to_string())?
            .ok_or_else(|| format!("push: missing config blob for {canonical}"))?;
    let manifest = parse_image_manifest(&record.manifest_json).map_err(|err| err.to_string())?;

    client
        .push_blob_from_file(
            &canonical,
            &manifest.config.digest,
            &config_path,
            auth.as_ref(),
        )
        .map_err(|err| err.to_string())?;
    for (layer, path) in manifest.layers.iter().zip(layer_paths.iter()) {
        if !path.exists() {
            return Err(format!("push: missing layer blob {}", layer.digest));
        }
        client
            .push_blob_from_file(&canonical, &layer.digest, path, auth.as_ref())
            .map_err(|err| err.to_string())?;
    }
    client
        .push_manifest_raw_with_media_type(
            &canonical,
            &record.manifest_json,
            &record.manifest_media_type,
            auth.as_ref(),
        )
        .map_err(|err| err.to_string())?;
    println!("push: image={canonical}");
    Ok(())
}

#[cfg(target_os = "linux")]
fn handle_scan(
    store: &LocalImageStore,
    image: &str,
    scanner: &str,
    authorization: &SurfaceAuthorization,
) -> Result<(), String> {
    let origin = RequestOrigin::cli_current().map_err(|error| error.to_string())?;
    let output = scan_image(store, image, scanner, authorization, &origin)?;
    println!("{output}");
    Ok(())
}

#[cfg(target_os = "linux")]
fn scan_image(
    store: &LocalImageStore,
    image: &str,
    scanner: &str,
    authorization: &SurfaceAuthorization,
    origin: &RequestOrigin,
) -> Result<String, String> {
    ensure_image_present(store, image, origin, authorization)?;
    let runtime_dir = runtime_dir();
    let layer_paths = resolve_layer_paths_with_store(&runtime_dir, image, store)
        .map_err(|err| format!("scan: missing image layers: {err}"))?;
    if layer_paths.is_empty() {
        return Err("scan: image has no layers".to_string());
    }
    let temp = tempfile::tempdir().map_err(|err| format!("scan: {err}"))?;
    let rootfs = temp.path().join("rootfs");
    let cas_root = runtime_dir.join("images").join("file-cas").join("blake3");
    construct_rootfs_with_dedup(&rootfs, &layer_paths, &cas_root)
        .map_err(|err| format!("scan: {err}"))?;

    let scanner = select_scanner(scanner)?;
    run_scanner(&scanner, &rootfs)
}

fn select_scanner(requested: &str) -> Result<String, String> {
    match requested {
        "auto" => {
            if command_exists("trivy") {
                Ok("trivy".to_string())
            } else if command_exists("grype") {
                Ok("grype".to_string())
            } else {
                Err("scan: install trivy or grype, or pass --scanner".to_string())
            }
        }
        "trivy" | "grype" => Ok(requested.to_string()),
        other => Err(format!("scan: unsupported scanner {other}")),
    }
}

fn run_scanner(scanner: &str, rootfs: &Path) -> Result<String, String> {
    let scanner_path = resolve_command_path(scanner)
        .ok_or_else(|| format!("scan: scanner executable is unavailable: {scanner}"))?;
    let output = match scanner {
        "trivy" => process::Command::new(&scanner_path)
            .args(["fs", "--quiet", "--format", "json"])
            .arg(rootfs)
            .output(),
        "grype" => process::Command::new(&scanner_path)
            .args(["dir:"])
            .arg(rootfs)
            .args(["--output", "json"])
            .output(),
        _ => return Err(format!("scan: unsupported scanner {scanner}")),
    }
    .map_err(|err| format!("scan: {err}"))?;

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        return Err(format!("scan: scanner failed: {}", stderr.trim()));
    }
    Ok(String::from_utf8_lossy(&output.stdout).to_string())
}

#[cfg(target_os = "linux")]
enum ComposePrerequisite {
    ImageBuild(ferro_core::dockerfile_build::ImageBuildPlan),
    ImagePull(ferro_core::image_fetch::ImageFetchPlan),
    VolumeCreate(ferro_core::volume_store::VolumeCreatePlan),
}

#[cfg(target_os = "linux")]
impl ComposePrerequisite {
    fn mutation(&self) -> ServiceMutation {
        match self {
            Self::ImageBuild(plan) => ServiceMutation::new(
                plan.canonical_tag(),
                FanoutAction::ImageBuild,
                plan.plan_digest(),
            ),
            Self::ImagePull(plan) => ServiceMutation::new(
                plan.canonical_reference(),
                FanoutAction::ImagePull,
                plan.plan_digest(),
            ),
            Self::VolumeCreate(plan) => {
                ServiceMutation::new(plan.name(), FanoutAction::VolumeCreate, plan.plan_digest())
            }
        }
    }
}

#[cfg(target_os = "linux")]
struct PreparedComposeService {
    name: String,
    instance: String,
    image: String,
    prerequisites: Vec<ComposePrerequisite>,
}

#[cfg(target_os = "linux")]
fn compose_project_volume_spec(
    project_dir: &Path,
    compose: &ferro_compose::ComposeFile,
    source: &str,
) -> Result<(String, String, BTreeMap<String, String>), String> {
    let Some(definition) = compose.volumes.as_ref().and_then(|volumes| volumes.get(source)) else {
        return Ok((source.to_string(), "local".to_string(), BTreeMap::new()));
    };
    let project = compose_default_network_name_with_declared(project_dir, compose.name.as_deref())
        .map_err(|error| format!("compose: project volume name: {error}"))?
        .strip_suffix("_default")
        .unwrap_or_default()
        .to_string();
    Ok((
        format!("{project}_{source}"),
        definition.driver.clone().unwrap_or_else(|| "local".to_string()),
        definition.driver_opts.clone(),
    ))
}

/// Image-derived inputs that compose binds into a child run authorization.
/// They are resolved before the child is authorized and then supplied to the
/// launcher so the authorized request is the request that executes.
#[cfg(target_os = "linux")]
#[derive(Debug, Clone)]
struct ResolvedRunImageExecution {
    command: Vec<String>,
    env: Vec<String>,
    workdir: Option<String>,
    user: Option<String>,
    health: Option<ferro_core::container_store::HealthConfig>,
    volume_targets: Vec<String>,
    volume_mounts: Vec<String>,
}

#[cfg(target_os = "linux")]
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
struct ComposeNetworkOwnership {
    project: String,
    networks: Vec<String>,
    #[serde(default)]
    rootless_networks: Vec<RootlessComposeNetwork>,
}

#[cfg(target_os = "linux")]
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
struct RootlessComposeNetwork {
    network: String,
    lease: ferro_core::runtime::RootlessNetworkLease,
}

/// Cleans up only coordinators which never gained a workload.  This covers
/// every early-return path in Compose-up (authorization, image preparation,
/// dependencies, and forwarding) without risking an active project's lease.
#[cfg(target_os = "linux")]
struct RootlessComposeLeaseCleanup {
    runtime_dir: PathBuf,
    unused: Vec<ferro_core::runtime::RootlessNetworkLease>,
}

#[cfg(target_os = "linux")]
impl RootlessComposeLeaseCleanup {
    fn new(runtime_dir: PathBuf) -> Self {
        Self { runtime_dir, unused: Vec::new() }
    }

    fn track(&mut self, lease: ferro_core::runtime::RootlessNetworkLease) {
        self.unused.push(lease);
    }

    fn keep(&mut self, lease: &ferro_core::runtime::RootlessNetworkLease) {
        self.unused.retain(|candidate| candidate != lease);
    }

    fn disarm(&mut self) {
        self.unused.clear();
    }
}

#[cfg(target_os = "linux")]
impl Drop for RootlessComposeLeaseCleanup {
    fn drop(&mut self) {
        for lease in self.unused.iter().rev() {
            let _ = ferro_core::runtime::stop_rootless_network_lease(&self.runtime_dir, lease);
        }
    }
}

#[cfg(target_os = "linux")]
fn compose_network_ownership_path(runtime_dir: &Path) -> std::path::PathBuf {
    runtime_dir.join("compose-networks.json")
}

#[cfg(target_os = "linux")]
fn load_compose_network_ownership(
    runtime_dir: &Path,
) -> Result<Vec<ComposeNetworkOwnership>, String> {
    let path = compose_network_ownership_path(runtime_dir);
    if !path.exists() {
        return Ok(Vec::new());
    }
    let content = std::fs::read_to_string(&path)
        .map_err(|error| format!("compose: failed to read network ownership: {error}"))?;
    serde_json::from_str(&content)
        .map_err(|error| format!("compose: failed to parse network ownership: {error}"))
}

#[cfg(target_os = "linux")]
fn save_compose_network_ownership(
    runtime_dir: &Path,
    ownership: &[ComposeNetworkOwnership],
) -> Result<(), String> {
    let path = compose_network_ownership_path(runtime_dir);
    let payload = serde_json::to_vec_pretty(ownership)
        .map_err(|error| format!("compose: failed to encode network ownership: {error}"))?;
    ferro_core::fs_atomic::write_atomic(&path, &payload)
        .map_err(|error| format!("compose: failed to write network ownership: {error}"))
}

#[cfg(target_os = "linux")]
fn compose_project_key(project: &ComposeProject) -> String {
    project
        .path
        .canonicalize()
        .unwrap_or_else(|_| project.path.clone())
        .display()
        .to_string()
}

#[cfg(target_os = "linux")]
#[cfg(test)]
fn compose_default_network_name(project_dir: &Path) -> Result<String, String> {
    compose_default_network_name_with_declared(project_dir, None)
}

#[cfg(target_os = "linux")]
fn compose_default_network_name_with_declared(
    project_dir: &Path,
    declared_name: Option<&str>,
) -> Result<String, String> {
    let raw = std::env::var("COMPOSE_PROJECT_NAME")
        .ok()
        .filter(|value| !value.trim().is_empty())
        .or_else(|| {
            declared_name
                .map(str::to_owned)
                .filter(|value| !value.trim().is_empty())
        })
        .or_else(|| {
            project_dir
                .file_name()
                .and_then(|name| name.to_str())
                .map(str::to_owned)
        })
        .unwrap_or_else(|| "ferrocrate".to_string());
    let mut project = raw
        .chars()
        .map(|ch| {
            if ch.is_ascii_alphanumeric() || ch == '-' || ch == '_' {
                ch.to_ascii_lowercase()
            } else {
                '_'
            }
        })
        .collect::<String>();
    while project.starts_with('_') {
        project.remove(0);
    }
    while project.ends_with('_') {
        project.pop();
    }
    if project.is_empty() {
        project = "ferrocrate".to_string();
    }
    let name = format!("{project}_default");
    validate_network_name(&name)?;
    Ok(name)
}

#[cfg(target_os = "linux")]
#[allow(clippy::too_many_arguments)]
fn prepare_compose_service(
    store: &LocalImageStore,
    volume_store: &LocalVolumeStore,
    origin: &RequestOrigin,
    authorization: &SurfaceAuthorization,
    project_dir: &Path,
    compose: &ferro_compose::ComposeFile,
    name: String,
    instance: String,
    service: &ComposeService,
) -> Result<PreparedComposeService, String> {
    let image = service
        .image
        .clone()
        .unwrap_or_else(|| format!("local/compose-{name}:latest"));
    let mut prerequisites = Vec::new();
    if let Some(build) = service.build.as_ref() {
        let context = build.context.as_deref().unwrap_or(".");
        let dockerfile = build.dockerfile.as_deref().unwrap_or("Dockerfile");
        let dockerfile_path = project_dir.join(context).join(dockerfile);
        prefetch_dockerfile_bases(store, origin, authorization, &dockerfile_path, None)?;
        let plan = ferro_core::dockerfile_build::prepare_dockerfile_build_with_contexts_and_build_args(
            &dockerfile_path,
            Some(&image),
            &runtime_dir(),
            CompressionFormat::Gzip,
            store,
            &HashMap::new(),
            build.args.as_ref().unwrap_or(&HashMap::new()),
        )
        .map_err(|error| error.to_string())?;
        prerequisites.push(ComposePrerequisite::ImageBuild(plan));
    } else if resolve_reference(store, &image)
        .map_err(|error| error.to_string())?
        .is_none()
    {
        let selector = normalize_selector(&image).map_err(|error| error.to_string())?;
        if selector.is_local_only() {
            return Err(format!("compose: image {image} was not found locally"));
        }
        prerequisites.push(ComposePrerequisite::ImagePull(
            ferro_core::image_fetch::inspect_image_binding(&image)
                .map_err(|error| error.to_string())?,
        ));
    }
    let mut planned_volumes = HashSet::new();
    if let Some(volumes) = service.volumes.as_ref() {
        for entry in volumes {
            let source = entry.split(':').next().unwrap_or("");
            if source.is_empty() || source.starts_with('.') || source.contains('/') {
                continue;
            }
            let (volume_name, driver, driver_opts) =
                compose_project_volume_spec(project_dir, compose, source)?;
            if planned_volumes.insert(volume_name.clone())
                && volume_store
                    .get(&volume_name)
                    .map_err(|error| error.to_string())?
                    .is_none()
            {
                prerequisites.push(ComposePrerequisite::VolumeCreate(
                    volume_store
                        .prepare_create(&volume_name, &driver, driver_opts)
                        .map_err(|error| error.to_string())?,
                ));
            }
        }
    }
    Ok(PreparedComposeService {
        name,
        instance,
        image,
        prerequisites,
    })
}

#[cfg(target_os = "linux")]
fn ensure_compose_networks(
    project: &ComposeProject,
    runtime_dir: &Path,
    default_network: &str,
    origin: &RequestOrigin,
    authorization: &SurfaceAuthorization,
) -> Result<Vec<String>, String> {
    let networks = project.compose.networks.as_ref();
    let default_needed = project.compose.services.values().any(|service| {
        if service.network_mode.is_some() {
            return false;
        }
        service.networks.as_ref().is_none_or(|names| {
            names.is_empty() || names.iter().any(|name| name.trim() == "default")
        })
    });
    let mut definitions = networks
        .into_iter()
        .flat_map(|values| values.iter())
        .map(|(name, definition)| {
            let effective_name = if name == "default" {
                default_network.to_string()
            } else {
                name.clone()
            };
            (
                effective_name,
                definition.driver.clone(),
                definition.external,
            )
        })
        .collect::<Vec<_>>();
    if default_needed
        && !definitions
            .iter()
            .any(|(name, _, _)| name == default_network)
    {
        definitions.push((default_network.to_string(), None, false));
    }
    definitions.sort_by(|left, right| left.0.cmp(&right.0));
    let needs_rootful_bridge = definitions.iter().any(|(_, driver, external)| {
        !external && driver.as_deref().unwrap_or("bridge") == "bridge"
    });
    let rootless_compose = !nix::unistd::Uid::effective().is_root() && needs_rootful_bridge;
    let mut records = load_networks(runtime_dir)?;
    let mut created = Vec::new();
    for (name, driver, external) in definitions {
        if is_builtin_network_mode(&name) {
            continue;
        }
        if external {
            if records.iter().any(|record| record.name == name) {
                continue;
            }
            return Err(format!("compose: external network {name} was not found"));
        }
        let driver = driver.as_deref().unwrap_or("bridge");
        if driver != "bridge" {
            return Err(format!(
                "compose: network {name} uses unsupported driver {driver}"
            ));
        }
        validate_network_name(&name)?;
        if records.iter().any(|record| record.name == name) {
            continue;
        }
        // Rootless containers receive an isolated slirp4netns network. The
        // first service becomes the network leader and subsequent services
        // join that leader's namespace, so no privileged bridge record or
        // kernel mutation is needed at Compose-up time.
        if rootless_compose {
            continue;
        }
        let record = create_network_record(&name, None, None, None, None)?;
        if records.iter().any(|existing| {
            existing.bridge_name == record.bridge_name && existing.name != record.name
        }) {
            return Err(format!(
                "compose: network {name} collides with bridge {}",
                record.bridge_name
            ));
        }
        let permit = authorization
            .authorize_named(
                origin,
                AuthorizationAction::NetworkCreate,
                ResourceKind::Network,
                &name,
                record.generation,
            )
            .map_err(|error| error.to_string())?;
        if !rootless_compose || cfg!(test) {
            execute_network_create(runtime_dir, &record, permit)?;
        }
        records.push(record);
        if rootless_compose {
            save_networks(runtime_dir, &records)?;
        }
        created.push(name);
    }
    if !created.is_empty() {
        let project_key = compose_project_key(project);
        let mut ownership = load_compose_network_ownership(runtime_dir)?;
        if let Some(entry) = ownership
            .iter_mut()
            .find(|entry| entry.project == project_key)
        {
            for name in &created {
                if !entry.networks.contains(name) {
                    entry.networks.push(name.clone());
                }
            }
            entry.networks.sort();
        } else {
            let mut networks = created.clone();
            networks.sort();
            ownership.push(ComposeNetworkOwnership {
                project: project_key,
                networks,
                rootless_networks: Vec::new(),
            });
        }
        ownership.sort_by(|left, right| left.project.cmp(&right.project));
        save_compose_network_ownership(runtime_dir, &ownership)?;
    }
    Ok(created)
}

#[cfg(target_os = "linux")]
fn rootless_compose_network_needs_lease(service: &ComposeService) -> bool {
    if nix::unistd::Uid::effective().is_root() {
        return false;
    }
    match service.network_mode.as_deref() {
        Some("host" | "none" | "wireguard") => false,
        Some(mode) if mode.starts_with("container:") => false,
        _ => true,
    }
}

#[cfg(target_os = "linux")]
fn rootless_compose_network_lease_key(project: &ComposeProject, network: &str) -> String {
    let project_key = compose_project_key(project);
    let digest = Sha256::digest([project_key.as_bytes(), b"\0", network.as_bytes()].concat());
    let suffix = digest[..16]
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect::<String>();
    format!("compose-{suffix}")
}

#[cfg(target_os = "linux")]
fn ensure_rootless_compose_network_lease(
    project: &ComposeProject,
    runtime_dir: &Path,
    network: &str,
) -> Result<ferro_core::runtime::RootlessNetworkLeaseAcquisition, String> {
    let acquisition = ferro_core::runtime::acquire_rootless_network_lease(
        runtime_dir,
        &rootless_compose_network_lease_key(project, network),
    )
    .map_err(|error| error.to_string())?;
    let project_key = compose_project_key(project);
    let mut ownership = load_compose_network_ownership(runtime_dir)?;
    let entry = if let Some(entry) = ownership.iter_mut().find(|entry| entry.project == project_key) {
        entry
    } else {
        ownership.push(ComposeNetworkOwnership {
            project: project_key.clone(),
            networks: Vec::new(),
            rootless_networks: Vec::new(),
        });
        ownership.last_mut().expect("project ownership was inserted")
    };
    entry.rootless_networks.retain(|entry| entry.network != network);
    entry.rootless_networks.push(RootlessComposeNetwork {
        network: network.to_string(),
        lease: acquisition.lease.clone(),
    });
    entry.rootless_networks.sort_by(|left, right| left.network.cmp(&right.network));
    ownership.sort_by(|left, right| left.project.cmp(&right.project));
    if let Err(error) = save_compose_network_ownership(runtime_dir, &ownership) {
        if acquisition.created {
            let _ = ferro_core::runtime::stop_rootless_network_lease(runtime_dir, &acquisition.lease);
        }
        return Err(error);
    }
    Ok(acquisition)
}

#[cfg(target_os = "linux")]
fn compose_project_network_binding(
    owners: &HashMap<String, ferro_core::runtime::RootlessNetworkLease>,
    service: &str,
    network: &str,
) -> Result<String, String> {
    let lease = owners.get(network).ok_or_else(|| {
        format!("compose: project network lease for {network} was not provisioned before service {service}")
    })?;
    if !ferro_core::runtime::rootless_network_lease_alive(lease) {
        return Err(format!("compose: project network lease for {network} is no longer alive"));
    }
    Ok(format!("container:pid:{}", lease.owner_pid))
}

#[cfg(target_os = "linux")]
fn compose_publish_uses_bridge_network(
    effective_network: &str,
    lease_backed_network: bool,
) -> bool {
    effective_network == "bridge" || (lease_backed_network && effective_network.starts_with("container:pid:"))
}

#[cfg(target_os = "linux")]
fn compose_rootless_network_binding(
    _runtime: &ContainerRuntime,
    service: &ComposeService,
    name: &str,
    default_network: &str,
    leases: &HashMap<String, ferro_core::runtime::RootlessNetworkLease>,
) -> Result<(String, Option<String>), String> {
    let logical = compose_service_network(service, name, default_network)?;
    if nix::unistd::Uid::effective().is_root()
        || matches!(logical.as_str(), "host" | "none" | "wireguard")
        || logical.starts_with("container:")
    {
        return Ok((logical, None));
    }
    Ok((
        compose_project_network_binding(leases, name, &logical)?,
        Some(logical),
    ))
}

#[cfg(target_os = "linux")]
fn remove_owned_compose_networks(
    project: &ComposeProject,
    runtime_dir: &Path,
    runtime: &ContainerRuntime,
    origin: &RequestOrigin,
    authorization: &SurfaceAuthorization,
) -> Result<(), String> {
    let project_key = compose_project_key(project);
    let mut ownership = load_compose_network_ownership(runtime_dir)?;
    let Some(entry) = ownership.iter().find(|entry| entry.project == project_key) else {
        return Ok(());
    };
    let associations = runtime.list().map_err(|error| error.to_string())?;
    let mut records = load_networks(runtime_dir)?;
    let rootless_compose = !nix::unistd::Uid::effective().is_root();
    for name in &entry.networks {
        let Some(record) = records.iter().find(|record| record.name == *name).cloned() else {
            continue;
        };
        if associations
            .iter()
            .any(|container| {
                container
                    .effective_network_endpoints()
                    .iter()
                    .any(|endpoint| endpoint.network_name == record.name)
            })
        {
            return Err(format!(
                "compose: cannot remove owned network {name} while containers remain attached"
            ));
        }
        if rootless_compose {
            records.retain(|entry| entry.name != record.name);
        } else {
            let permit = authorization
                .authorize_named(
                    origin,
                    AuthorizationAction::NetworkDelete,
                    ResourceKind::Network,
                    &record.name,
                    record.generation,
                )
                .map_err(|error| error.to_string())?;
            execute_network_remove(runtime_dir, &record, &associations, permit)?;
        }
    }
    // Rootless project networks have no kernel bridge record.  Their durable
    // coordinator is nevertheless owned by this Compose project and must be
    // torn down only after every namespace consumer has gone away.
    for owned in &entry.rootless_networks {
        let binding = format!("container:pid:{}", owned.lease.owner_pid);
        if associations.iter().any(|container| {
            container
                .effective_network_endpoints()
                .iter()
                .any(|endpoint| endpoint.network_name == binding)
        }) {
            return Err(format!(
                "compose: cannot remove rootless network {} while containers remain attached",
                owned.network
            ));
        }
        ferro_core::runtime::stop_rootless_network_lease(runtime_dir, &owned.lease)
            .map_err(|error| format!("compose: remove rootless network {}: {error}", owned.network))?;
    }
    if rootless_compose {
        save_networks(runtime_dir, &records)?;
    }
    ownership.retain(|entry| entry.project != project_key);
    save_compose_network_ownership(runtime_dir, &ownership)
}

#[cfg(target_os = "linux")]
/// Whether a Compose service's restart policy relaunches it after exit, for
/// the attached-up liveness loop.
#[cfg(target_os = "linux")]
#[derive(Clone, Copy)]
enum ComposeRestartEligibility {
    Always,
    OnFailure,
    No,
}

/// Map every service instance name (including replica suffixes) to its
/// restart eligibility.
#[cfg(target_os = "linux")]
fn compose_restart_eligible_instances(
    services: &HashMap<String, ferro_compose::Service>,
) -> HashMap<String, ComposeRestartEligibility> {
    let mut out = HashMap::new();
    for (name, service) in services {
        let eligibility = match service.restart.as_deref() {
            Some("always") | Some("unless-stopped") => ComposeRestartEligibility::Always,
            Some("on-failure") => ComposeRestartEligibility::OnFailure,
            _ => ComposeRestartEligibility::No,
        };
        let replicas = service
            .deploy
            .as_ref()
            .and_then(|deploy| deploy.replicas)
            .unwrap_or(1);
        for index in 1..=replicas {
            let instance = if replicas == 1 {
                name.clone()
            } else {
                format!("{name}-{index}")
            };
            out.insert(instance, eligibility);
        }
    }
    out
}

fn handle_compose(
    runtime: &ContainerRuntime,
    store: &LocalImageStore,
    volume_store: &LocalVolumeStore,
    authenticated_origin: &RequestOrigin,
    file: Option<&str>,
    command: ComposeCommands,
) -> Result<String, String> {
    let path = find_compose_file(file).map_err(|err| err.to_string())?;
    let project = ComposeProject::load(&path).map_err(|err| err.to_string())?;
    let replay_store = FanoutReplayStore::open(runtime_dir()).map_err(|error| error.to_string())?;
    let project_dir = path
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .unwrap_or_else(|| Path::new("."))
        .canonicalize()
        .map_err(|error| format!("compose: project directory cannot be resolved: {error}"))?;
    let default_network =
        compose_default_network_name_with_declared(&project_dir, project.compose.name.as_deref())?;
    let mut output = String::new();
    match command {
        ComposeCommands::Up {
            profile,
            build: _,
            detach,
            services,
        } => {
            // Compose is a detached CLI operation: services must outlive the
            // short-lived `compose up` launcher just like Docker daemon
            // workloads. Without this lease override, the parent-death
            // safeguard kills valid services before a subsequent `compose
            // down` can reconcile them.
            unsafe { std::env::set_var("FERROCRATE_DETACH_WORKLOAD", "1") };
            let order = compose_up(&project).map_err(|err| err.to_string())?;
            let enabled = build_compose_enabled_set(&project, &profile)?;
            let requested = compose_service_selection(&project, &services)?;
            let selected_services: Vec<_> = order
                .into_iter()
                .filter(|name| enabled.contains(name) && requested.contains(name))
                .collect();
            let selected: Vec<(String, String)> = selected_services
                .into_iter()
                .flat_map(|name| {
                    let replicas = project
                        .compose
                        .services
                        .get(&name)
                        .and_then(|service| service.deploy.as_ref())
                        .and_then(|deploy| deploy.replicas)
                        .unwrap_or(1);
                    (1..=replicas)
                        .map(|index| {
                            let instance = if replicas == 1 {
                                name.clone()
                            } else {
                                format!("{name}-{index}")
                            };
                            (name.clone(), instance)
                        })
                        .collect::<Vec<_>>()
                })
                .collect();
            let parent_origin = authenticated_origin.clone();
            let mut parent_hasher = Sha256::new();
            parent_hasher.update(b"ferrocrate/compose-parent/v1");
            parent_hasher.update(std::process::id().to_be_bytes());
            parent_hasher.update(
                SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap_or_default()
                    .as_nanos()
                    .to_be_bytes(),
            );
            let parent_hash: [u8; 32] = parent_hasher.finalize().into();
            let mut parent_id = [0; 16];
            parent_id.copy_from_slice(&parent_hash[..16]);
            let (policy_generation, policy_digest) = runtime.policy_binding();
            let deadline = SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_millis()
                .saturating_add(300_000)
                .min(u64::MAX as u128) as u64;
            let surface_authorization = runtime
                .surface_authorization()
                .map_err(|error| error.to_string())?;
            let prepared: Vec<_> = selected
                .into_iter()
                .map(|(name, instance)| {
                    let service = project
                        .compose
                        .services
                        .get(&name)
                        .ok_or_else(|| format!("compose: missing service {name}"))?;
                    prepare_compose_service(
                        store,
                        volume_store,
                        &parent_origin,
                        &surface_authorization,
                        &project_dir,
                        &project.compose,
                        name,
                        instance,
                        service,
                    )
                })
                .collect::<Result<_, _>>()?;
            ensure_compose_networks(
                &project,
                &runtime_dir(),
                &default_network,
                &parent_origin,
                &surface_authorization,
            )?;
            let mut failures = Vec::new();
            // A project network is owned by a dedicated coordinator, rather
            // than by whichever application service happens to start first.
            // In particular, a short-lived migration service must not tear
            // down the namespace while its followers are still joining it.
            let mut rootless_network_leases = HashMap::<
                String,
                ferro_core::runtime::RootlessNetworkLease,
            >::new();
            let mut rootless_lease_cleanup = RootlessComposeLeaseCleanup::new(runtime_dir());
            for prepared_service in &prepared {
                let service = project
                    .compose
                    .services
                    .get(&prepared_service.name)
                    .ok_or_else(|| format!("compose: missing service {}", prepared_service.name))?;
                if !rootless_compose_network_needs_lease(service) {
                    continue;
                }
                let logical = compose_service_network(service, &prepared_service.name, &default_network)?;
                if rootless_network_leases.contains_key(&logical) {
                    continue;
                }
                let acquisition =
                    ensure_rootless_compose_network_lease(&project, &runtime_dir(), &logical)?;
                if acquisition.created {
                    rootless_lease_cleanup.track(acquisition.lease.clone());
                }
                rootless_network_leases.insert(logical, acquisition.lease);
            }
            let prepared_names: Vec<String> = prepared
                .iter()
                .map(|prepared| prepared.instance.clone())
                .collect();
            for prepared in prepared {
                let service = project
                    .compose
                    .services
                    .get(&prepared.name)
                    .ok_or_else(|| format!("compose: missing service {}", prepared.name))?;
                let (effective_compose_network, logical_network) =
                    compose_rootless_network_binding(
                        runtime,
                        service,
                        &prepared.name,
                        &default_network,
                        &rootless_network_leases,
                    )?;
                let mut mutations = prepared
                    .prerequisites
                    .iter()
                    .map(ComposePrerequisite::mutation)
                    .collect::<Vec<_>>();
                let mut image_execution = if mutations.is_empty() {
                    Some(resolve_compose_run_image_execution(
                        &runtime_dir(),
                        store,
                        &prepared.image,
                        &project_dir,
                        service,
                        service.entrypoint.as_deref(),
                        &compose_service_command(service),
                    )?)
                } else {
                    None
                };
                if let Some(image_execution) = image_execution.as_mut() {
                    resolve_compose_image_volume_mounts(
                        image_execution,
                        volume_store,
                        &project_dir,
                        &project.compose,
                        service,
                        &parent_origin,
                        &surface_authorization,
                    )?;
                }
                let initial_run_digest = if mutations.is_empty() {
                    compose_service_execution_digest(
                        runtime,
                        store,
                        volume_store,
                        &project_dir,
                        &project.compose,
                        &default_network,
                        &prepared.name,
                        service,
                        &prepared.instance,
                        &prepared.image,
                        Some(&effective_compose_network),
                        image_execution
                            .as_ref()
                            .expect("image execution is resolved without prerequisites"),
                    )?
                    .1
                } else {
                    [0; 32]
                };
                mutations.push(ServiceMutation::new(
                    &prepared.instance,
                    FanoutAction::ContainerRun,
                    initial_run_digest,
                ));
                let root_plan = FanoutPlan::derive(
                    parent_id,
                    policy_generation,
                    policy_digest,
                    deadline,
                    0,
                    mutations,
                )
                .map_err(|error| error.to_string())?;
                let mut current_plan = root_plan.clone();
                let mut predecessor = None;
                let mut predecessor_outcome = [0; 32];
                let mut prerequisite_failed = false;
                for (ordinal, prerequisite) in prepared.prerequisites.into_iter().enumerate() {
                    let mutation = prerequisite.mutation();
                    let child = if let Some(previous) = predecessor.as_ref() {
                        current_plan = current_plan
                            .derive_dependent(previous, predecessor_outcome, mutation)
                            .map_err(|error| error.to_string())?;
                        current_plan.children()[0].clone()
                    } else {
                        root_plan.children()[ordinal].clone()
                    };
                    if let Err(error) = current_plan
                        .verify_child(&child, current_unix_ms())
                        .and_then(|_| replay_store.claim(&child))
                    {
                        failures.push(format!(
                            "{} prerequisite denied/skipped: {error}",
                            prepared.instance
                        ));
                        prerequisite_failed = true;
                        break;
                    }
                    if let Err(error) = execute_compose_prerequisite(
                        prerequisite,
                        &child,
                        &parent_origin,
                        &surface_authorization,
                        store,
                        volume_store,
                    ) {
                        failures.push(format!(
                            "{} prerequisite failed: {error}",
                            prepared.instance
                        ));
                        prerequisite_failed = true;
                        break;
                    }
                    predecessor_outcome = compose_predecessor_outcome_digest(&child);
                    predecessor = Some(child);
                }
                if prerequisite_failed {
                    continue;
                }
                if let Some(depends_on) = service.depends_on.as_ref() {
                    wait_for_compose_dependencies(runtime, depends_on)
                        .map_err(|error| format!("compose partial result: {error}"))?;
                }
                let mut image_execution = image_execution.unwrap_or(resolve_compose_run_image_execution(
                    &runtime_dir(),
                    store,
                    &prepared.image,
                    &project_dir,
                    service,
                    service.entrypoint.as_deref(),
                    &compose_service_command(service),
                )?);
                resolve_compose_image_volume_mounts(
                    &mut image_execution,
                    volume_store,
                    &project_dir,
                    &project.compose,
                    service,
                    &parent_origin,
                    &surface_authorization,
                )?;
                let run_digest = compose_service_execution_digest(
                    runtime,
                    store,
                    volume_store,
                    &project_dir,
                    &project.compose,
                    &default_network,
                    &prepared.name,
                    service,
                    &prepared.instance,
                    &prepared.image,
                    Some(&effective_compose_network),
                    &image_execution,
                )?
                .1;
                let run_child = if let Some(previous) = predecessor.as_ref() {
                    current_plan = current_plan
                        .derive_dependent(
                            previous,
                            predecessor_outcome,
                            ServiceMutation::new(
                                &prepared.instance,
                                FanoutAction::ContainerRun,
                                run_digest,
                            ),
                        )
                        .map_err(|error| error.to_string())?;
                    current_plan.children()[0].clone()
                } else {
                    root_plan.children()[0].clone()
                };
                if let Err(error) = current_plan
                    .verify_child(&run_child, current_unix_ms())
                    .and_then(|_| replay_store.claim(&run_child))
                {
                    failures.push(format!("{} run denied/skipped: {error}", prepared.instance));
                    continue;
                }
                let child_runtime = runtime.request_scoped(
                    ferro_core::authorization::RequestOrigin::compose_child(
                        &parent_origin,
                        *run_child.child_id(),
                        *run_child.parent_request_id(),
                        *run_child.idempotency_key(),
                        ferro_core::authorization::Action::ContainerRun,
                        &prepared.instance,
                        *run_child.request_digest(),
                        run_child.deadline_unix_ms(),
                        run_child.policy_generation(),
                        *run_child.policy_digest(),
                        run_child.attempt(),
                        run_child.ordinal(),
                        *run_child.plan_digest(),
                    ),
                );
                if let Err(error) = run_compose_service(
                    &child_runtime,
                    store,
                    volume_store,
                    &project_dir,
                    &project.compose,
                    &default_network,
                    &prepared.name,
                    service,
                    Some(&prepared.instance),
                    Some(&prepared.image),
                    Some(&effective_compose_network),
                    logical_network
                        .as_ref()
                        .is_some_and(|network| rootless_network_leases.contains_key(network)),
                    &image_execution,
                ) {
                    failures.push(format!("{} run failed: {error}", prepared.instance));
                } else if let Err(error) = connect_compose_secondary_networks(
                    runtime,
                    &runtime_dir(),
                    service,
                    &prepared.name,
                    &default_network,
                    &prepared.instance,
                    &parent_origin,
                    &surface_authorization,
                ) {
                    let rollback = resolve_container_id(runtime, &prepared.instance)
                        .and_then(|id| {
                            runtime.kill(&id).map_err(|failure| failure.to_string())?;
                            runtime.remove(&id).map_err(|failure| failure.to_string())
                        })
                        .err()
                        .map(|failure| format!("; rollback failed: {failure}"))
                        .unwrap_or_default();
                    failures.push(format!(
                        "{} network attachment failed: {error}{rollback}",
                        prepared.instance
                    ));
                } else if let Some(logical) = logical_network {
                    let lease = rootless_network_leases
                        .get(&logical)
                        .expect("logical rootless network has a pre-provisioned lease");
                    let mappings = parse_publish(&compose_service_ports(service))?;
                    if let Err(error) = ferro_core::runtime::add_rootless_network_lease_forwards(
                        &runtime_dir(),
                        lease,
                        &mappings,
                    ) {
                        let rollback = resolve_container_id(runtime, &prepared.instance)
                            .and_then(|id| {
                                runtime.kill(&id).map_err(|failure| failure.to_string())?;
                                runtime.remove(&id).map_err(|failure| failure.to_string())
                            })
                            .err()
                            .map(|failure| format!("; rollback failed: {failure}"))
                            .unwrap_or_default();
                        failures.push(format!(
                            "{} rootless network forwarding failed: {error}{rollback}",
                            prepared.instance
                        ));
                    } else {
                        rootless_lease_cleanup.keep(lease);
                    }
                }
            }
            if !failures.is_empty() {
                return Err(format!("compose partial result: {}", failures.join("; ")));
            }
            rootless_lease_cleanup.disarm();
            if !detach {
                // Attached up keeps this process alive while project
                // containers run, mirroring Docker's attached semantics. The
                // in-process restart supervisor (restart: always/on-failure)
                // only functions while its launching process lives, so an
                // attached up is the supported restart mode for CLI Compose.
                // A container between restarts shows a momentary `exited`
                // status; restart-eligible services stay attached through it.
                let restart_eligible =
                    compose_restart_eligible_instances(&project.compose.services);
                // A container record becomes queryable only after its launch
                // mutation finalizes; do not treat not-yet-visible instances
                // as finished.
                let mut observed: std::collections::HashSet<String> =
                    std::collections::HashSet::new();
                loop {
                    let records = runtime.list().map_err(|err| err.to_string())?;
                    let any_active = records.iter().any(|record| {
                        let Some(name) = record.name.as_deref() else {
                            return false;
                        };
                        if !prepared_names.iter().any(|prepared| prepared == name) {
                            return false;
                        }
                        observed.insert(name.to_string());
                        let eligibility = restart_eligible.get(name);
                        match record.status.as_str() {
                            // `exited` between restarts: stay attached while
                            // the policy will relaunch this instance. A manual
                            // stop or kill also publishes `exited`, so the
                            // user-stop flag decides, not the status alone.
                            "exited" if !record.user_stopped => match eligibility {
                                Some(ComposeRestartEligibility::Always) => true,
                                Some(ComposeRestartEligibility::OnFailure) => {
                                    record.last_exit_code.is_some_and(|code| code != 0)
                                }
                                _ => false,
                            },
                            "exited" | "stopped" | "killed" => false,
                            // Any pre-terminal state (created/pending/running/
                            // paused/…) keeps the attached up alive.
                            _ => true,
                        }
                    });
                    let pending_visibility = prepared_names
                        .iter()
                        .any(|name| !observed.contains(name));
                    if !any_active && !pending_visibility {
                        break;
                    }
                    std::thread::sleep(Duration::from_millis(500));
                }
            }
        }
        ComposeCommands::Watch { profile, interval } => {
            let mut last_mtime = latest_mtime(&project_dir)?;
            loop {
                handle_compose(
                    runtime,
                    store,
                    volume_store,
                    authenticated_origin,
                    file,
                    ComposeCommands::Up {
                        profile: profile.clone(),
                        build: false,
                        detach: true,
                        services: Vec::new(),
                    },
                )?;
                loop {
                    std::thread::sleep(Duration::from_secs(interval));
                    let current = latest_mtime(&project_dir)?;
                    if current > last_mtime {
                        last_mtime = current;
                        break;
                    }
                }
                handle_compose(
                    runtime,
                    store,
                    volume_store,
                    authenticated_origin,
                    file,
                    ComposeCommands::Down {
                        volumes: false,
                        services: Vec::new(),
                    },
                )?;
            }
        }
        ComposeCommands::Stop { timeout, services } => {
            let order = compose_down(&project).map_err(|err| err.to_string())?;
            compose_lifecycle_records(runtime, &order, &services, |id| {
                handle_stop(runtime, id, timeout)
            })?;
        }
        ComposeCommands::Start { services } => {
            let order = compose_up(&project).map_err(|err| err.to_string())?;
            compose_lifecycle_records(runtime, &order, &services, |id| handle_start(runtime, id))?;
        }
        ComposeCommands::Restart { timeout, services } => {
            let order = compose_up(&project).map_err(|err| err.to_string())?;
            compose_lifecycle_records(runtime, &order, &services, |id| {
                handle_restart(runtime, id, timeout)
            })?;
        }
        ComposeCommands::Pull { services } => {
            let authorization = runtime.surface_authorization().map_err(|error| error.to_string())?;
            compose_pull_with_origin(&project, &services, authenticated_origin, |image, origin| {
                handle_pull_authorized(
                    store,
                    image,
                    false,
                    origin,
                    &authorization,
                )
            })?;
        }
        ComposeCommands::Config => {
            output = serde_yaml::to_string(&project.compose).map_err(|error| error.to_string())?;
        }
        ComposeCommands::Down { services, volumes: _ } => {
            let order = compose_down(&project).map_err(|err| err.to_string())?;
            let containers = runtime.list().map_err(|err| err.to_string())?;
            let requested = compose_explicit_service_selection(&project, &services)?;
            let selected: Vec<_> = order
                .into_iter()
                .filter(|name| requested.contains(name))
                .flat_map(|name| {
                    containers
                        .iter()
                        .filter(move |rec| {
                            rec.name
                                .as_deref()
                                .map(|val| val == name || val.starts_with(&format!("{name}-")))
                                .unwrap_or(false)
                        })
                        .cloned()
                        .collect::<Vec<_>>()
                })
                .collect();
            let parent_origin = authenticated_origin.clone();
            let surface_authorization = runtime
                .surface_authorization()
                .map_err(|error| error.to_string())?;
            let mut parent_hasher = Sha256::new();
            parent_hasher.update(b"ferrocrate/compose-down-parent/v1");
            parent_hasher.update(
                SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap_or_default()
                    .as_nanos()
                    .to_be_bytes(),
            );
            let parent_hash: [u8; 32] = parent_hasher.finalize().into();
            let mut parent_id = [0; 16];
            parent_id.copy_from_slice(&parent_hash[..16]);
            let (generation, policy_digest) = runtime.policy_binding();
            let deadline = SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .unwrap_or_default()
                .as_millis()
                .saturating_add(300_000)
                .min(u64::MAX as u128) as u64;
            let mutations = selected.iter().flat_map(|record| {
                [FanoutAction::ContainerStop, FanoutAction::ContainerDelete]
                    .into_iter()
                    .map(move |action| {
                        let runtime_action = match action {
                            FanoutAction::ContainerStop => {
                                ferro_core::authorization::Action::ContainerStop
                            }
                            FanoutAction::ContainerDelete => {
                                ferro_core::authorization::Action::ContainerDelete
                            }
                            FanoutAction::ContainerRun
                            | FanoutAction::ImagePull
                            | FanoutAction::VolumeCreate
                            | FanoutAction::ImageBuild => unreachable!(),
                        };
                        ServiceMutation::new(
                            record.name.clone().unwrap_or_else(|| record.id.clone()),
                            action,
                            if action == FanoutAction::ContainerDelete {
                                Sha256::digest(
                                    [
                                        b"ferrocrate/compose-down-delete-intent/v1".as_slice(),
                                        record.id.as_bytes(),
                                    ]
                                    .concat(),
                                )
                                .into()
                            } else {
                                ferro_core::authorization::compose_down_executor_digest(
                                    record,
                                    runtime_action,
                                )
                            },
                        )
                    })
            });
            let fanout =
                FanoutPlan::derive(parent_id, generation, policy_digest, deadline, 0, mutations)
                    .map_err(|error| error.to_string())?;
            let mut failures = Vec::new();
            for (index, record) in selected.iter().enumerate() {
                let stop_child = &fanout.children()[index * 2];
                if let Err(error) = fanout
                    .verify_child(stop_child, current_unix_ms())
                    .and_then(|_| replay_store.claim(stop_child))
                {
                    failures.push(format!("{}: stop denied/skipped: {error}", record.id));
                    continue;
                }
                let action = ferro_core::authorization::Action::ContainerStop;
                let resource = record.name.clone().unwrap_or_else(|| record.id.clone());
                let scoped = runtime.request_scoped(
                    ferro_core::authorization::RequestOrigin::compose_child(
                        &parent_origin,
                        *stop_child.child_id(),
                        parent_id,
                        *stop_child.idempotency_key(),
                        action,
                        resource.clone(),
                        *stop_child.request_digest(),
                        stop_child.deadline_unix_ms(),
                        stop_child.policy_generation(),
                        *stop_child.policy_digest(),
                        stop_child.attempt(),
                        stop_child.ordinal(),
                        *stop_child.plan_digest(),
                    ),
                );
                if let Err(error) = scoped.stop(&record.id, std::time::Duration::from_secs(5)) {
                    failures.push(format!(
                        "{}: stop failed; delete skipped: {error}",
                        record.id
                    ));
                    continue;
                }
                let stopped = runtime
                    .inspect(&record.id)
                    .map_err(|error| error.to_string())?;
                let delete_digest = ferro_core::authorization::compose_down_executor_digest(
                    &stopped,
                    ferro_core::authorization::Action::ContainerDelete,
                );
                let predecessor_digest: [u8; 32] = Sha256::digest(
                    [
                        b"ferrocrate/compose-predecessor-outcome/v1".as_slice(),
                        stop_child.child_id(),
                        stopped.status.as_bytes(),
                        &stopped.mutation_generation.to_be_bytes(),
                        fanout.plan_digest(),
                    ]
                    .concat(),
                )
                .into();
                let delete_plan = fanout
                    .derive_dependent(
                        stop_child,
                        predecessor_digest,
                        ServiceMutation::new(
                            resource.clone(),
                            FanoutAction::ContainerDelete,
                            delete_digest,
                        ),
                    )
                    .map_err(|error| error.to_string())?;
                let delete_child = &delete_plan.children()[0];
                let delete_parent = *delete_child.parent_request_id();
                if let Err(error) = delete_plan
                    .verify_child(delete_child, current_unix_ms())
                    .and_then(|_| replay_store.claim(delete_child))
                {
                    failures.push(format!("{}: delete denied/skipped: {error}", record.id));
                    continue;
                }
                let delete_runtime = runtime.request_scoped(
                    ferro_core::authorization::RequestOrigin::compose_child(
                        &parent_origin,
                        *delete_child.child_id(),
                        delete_parent,
                        *delete_child.idempotency_key(),
                        ferro_core::authorization::Action::ContainerDelete,
                        resource,
                        *delete_child.request_digest(),
                        delete_child.deadline_unix_ms(),
                        delete_child.policy_generation(),
                        *delete_child.policy_digest(),
                        delete_child.attempt(),
                        delete_child.ordinal(),
                        *delete_child.plan_digest(),
                    ),
                );
                if let Err(error) = delete_runtime.remove(&record.id) {
                    failures.push(format!("{}: delete failed: {error}", record.id));
                }
            }
            if !failures.is_empty() {
                return Err(format!(
                    "compose down partial result: {}",
                    failures.join("; ")
                ));
            }
            if services.is_empty() {
                remove_owned_compose_networks(
                    &project,
                    &runtime_dir(),
                    runtime,
                    &parent_origin,
                    &surface_authorization,
                )?;
            }
        }
        ComposeCommands::Ps => {
            let services = compose_ps(&project).map_err(|err| err.to_string())?;
            output = format!("compose ps: {:?}\n", services);
        }
        ComposeCommands::Logs { tail, services } => {
            let order = compose_logs(&project).map_err(|err| err.to_string())?;
            let requested = compose_explicit_service_selection(&project, &services)?;
            for service in order.into_iter().filter(|name| requested.contains(name)) {
                for record in compose_lifecycle_records_for_service(runtime, &service)? {
                    let (stdout, stderr) = runtime.logs_split(&record.id).map_err(|error| error.to_string())?;
                    let combined = format!("{stdout}{stderr}");
                    let lines = match tail {
                        Some(limit) => combined
                            .lines()
                            .rev()
                            .take(limit)
                            .collect::<Vec<_>>()
                            .into_iter()
                            .rev()
                            .collect::<Vec<_>>()
                            .join("\n"),
                        None => combined.trim_end_matches('\n').to_string(),
                    };
                    if !lines.is_empty() {
                        output.push_str(&format!("{service}  | {lines}\n"));
                    }
                }
            }
        }
    }
    Ok(output)
}

#[cfg(target_os = "linux")]
fn compose_pull_with_origin(
    project: &ComposeProject,
    services: &[String],
    authenticated_origin: &RequestOrigin,
    mut pull: impl FnMut(&str, &RequestOrigin) -> Result<(), String>,
) -> Result<(), String> {
    let order = compose_up(project).map_err(|error| error.to_string())?;
    let requested = compose_explicit_service_selection(project, services)?;
    for name in order.into_iter().filter(|name| requested.contains(name)) {
        let service = project
            .compose
            .services
            .get(&name)
            .expect("service from graph");
        let image = service
            .image
            .as_deref()
            .ok_or_else(|| format!("compose: service {name} has no image"))?;
        pull(image, authenticated_origin)?;
    }
    Ok(())
}

#[cfg(target_os = "linux")]
fn build_compose_enabled_set(
    project: &ComposeProject,
    profiles: &[String],
) -> Result<HashSet<String>, String> {
    let mut enabled = HashSet::new();
    for (name, service) in &project.compose.services {
        let active = match service.profiles.as_ref() {
            None => true,
            Some(list) if list.is_empty() => true,
            Some(list) => profiles.iter().any(|profile| list.contains(profile)),
        };
        if active {
            enabled.insert(name.clone());
        }
    }

    for (name, service) in &project.compose.services {
        if !enabled.contains(name) {
            continue;
        }
        if let Some(depends_on) = &service.depends_on {
            for dep in depends_on.iter() {
                if !enabled.contains(dep) {
                    return Err(format!(
                        "compose: service {name} depends on disabled profile service {dep}"
                    ));
                }
            }
        }
    }

    Ok(enabled)
}

#[cfg(target_os = "linux")]
fn compose_service_selection(
    project: &ComposeProject,
    services: &[String],
) -> Result<HashSet<String>, String> {
    if services.is_empty() {
        return Ok(project.compose.services.keys().cloned().collect());
    }
    let mut selected = HashSet::new();
    let mut pending = services.to_vec();
    while let Some(name) = pending.pop() {
        if !selected.insert(name.clone()) {
            continue;
        }
        let service = project
            .compose
            .services
            .get(&name)
            .ok_or_else(|| format!("compose: unknown service {name}"))?;
        if let Some(depends_on) = &service.depends_on {
            pending.extend(depends_on.iter().cloned());
        }
    }
    Ok(selected)
}

#[cfg(target_os = "linux")]
fn compose_explicit_service_selection(
    project: &ComposeProject,
    services: &[String],
) -> Result<HashSet<String>, String> {
    if services.is_empty() {
        return Ok(project.compose.services.keys().cloned().collect());
    }
    let selected: HashSet<_> = services.iter().cloned().collect();
    for service in &selected {
        if !project.compose.services.contains_key(service) {
            return Err(format!("compose: unknown service {service}"));
        }
    }
    Ok(selected)
}

#[cfg(target_os = "linux")]
fn compose_lifecycle_records(
    runtime: &ContainerRuntime,
    order: &[String],
    services: &[String],
    mut operation: impl FnMut(&str) -> Result<(), String>,
) -> Result<(), String> {
    let requested: HashSet<_> = services.iter().map(String::as_str).collect();
    let records = runtime.list().map_err(|error| error.to_string())?;
    let mut failures = Vec::new();
    for service in order {
        if !requested.is_empty() && !requested.contains(service.as_str()) {
            continue;
        }
        for record in records.iter().filter(|record| {
            record.name.as_deref().is_some_and(|name| {
                name == service || name.starts_with(&format!("{service}-"))
            })
        }) {
            if let Err(error) = operation(&record.id) {
                failures.push(format!("{}: {error}", record.id));
            }
        }
    }
    if failures.is_empty() {
        Ok(())
    } else {
        Err(format!("compose lifecycle partial result: {}", failures.join("; ")))
    }
}

#[cfg(target_os = "linux")]
fn compose_lifecycle_records_for_service(
    runtime: &ContainerRuntime,
    service: &str,
) -> Result<Vec<ferro_core::container_store::ContainerRecord>, String> {
    let replica_prefix = format!("{service}-");
    Ok(runtime
        .list()
        .map_err(|error| error.to_string())?
        .into_iter()
        .filter(|record| {
            record.name.as_deref().is_some_and(|name| {
                name == service || name.starts_with(&replica_prefix)
            })
        })
        .collect())
}

#[cfg(target_os = "linux")]
fn wait_for_compose_dependencies(
    runtime: &ContainerRuntime,
    depends_on: &ComposeDependsOn,
) -> Result<(), String> {
    match depends_on {
        ComposeDependsOn::Simple(_) => Ok(()),
        ComposeDependsOn::Conditional(map) => {
            for (service, condition) in map {
                match condition.condition.as_str() {
                    "service_started" => {}
                    "service_healthy" => wait_for_compose_health(runtime, service)?,
                    "service_completed_successfully" => {
                        wait_for_compose_completion(runtime, service)?
                    }
                    other => {
                        return Err(format!(
                            "compose: unknown depends_on condition {other} for {service}"
                        ));
                    }
                }
            }
            Ok(())
        }
    }
}

#[cfg(target_os = "linux")]
fn wait_for_compose_completion(runtime: &ContainerRuntime, service: &str) -> Result<(), String> {
    let ids = compose_dependency_container_ids(runtime, service)?;
    let deadline = Instant::now() + Duration::from_secs(30);
    loop {
        let mut all_complete = true;
        for id in &ids {
            let record = runtime.inspect(id).map_err(|err| err.to_string())?;
            if record.status == "exited" {
                let code = record.last_exit_code.unwrap_or(0);
                if code != 0 {
                    return Err(format!(
                        "compose: dependency {service} exited with status {code}"
                    ));
                }
                continue;
            }
            if matches!(record.status.as_str(), "removed" | "quarantined") {
                return Err(format!(
                    "compose: dependency {service} disappeared before successful completion"
                ));
            }
            all_complete = false;
        }
        if all_complete {
            return Ok(());
        }
        if Instant::now() >= deadline {
            return Err(format!(
                "compose: timed out waiting for {service} to complete successfully"
            ));
        }
        std::thread::sleep(Duration::from_millis(250));
    }
}

#[cfg(target_os = "linux")]
fn wait_for_compose_health(runtime: &ContainerRuntime, service: &str) -> Result<(), String> {
    let ids = compose_dependency_container_ids(runtime, service)?;
    let deadline = Instant::now() + Duration::from_secs(30);
    loop {
        let mut all_healthy = true;
        for id in &ids {
            let record = runtime.inspect(id).map_err(|err| err.to_string())?;
            match record.health_status.as_str() {
                "healthy" => {}
                "unhealthy" => {
                    return Err(format!("compose: dependency {service} is unhealthy"));
                }
                "none" => {
                    return Err(format!("compose: dependency {service} has no healthcheck"));
                }
                _ => all_healthy = false,
            }
        }
        if all_healthy {
            return Ok(());
        }

        if Instant::now() >= deadline {
            return Err(format!(
                "compose: timed out waiting for {service} to become healthy"
            ));
        }
        std::thread::sleep(Duration::from_millis(250));
    }
}

#[cfg(target_os = "linux")]
fn compose_dependency_container_ids(
    runtime: &ContainerRuntime,
    service: &str,
) -> Result<Vec<String>, String> {
    let replica_prefix = format!("{service}-");
    let mut ids = runtime
        .list()
        .map_err(|error| error.to_string())?
        .into_iter()
        .filter(|record| {
            record.name.as_deref().is_some_and(|name| {
                name == service
                    || name
                        .strip_prefix(&replica_prefix)
                        .is_some_and(|suffix| !suffix.is_empty() && suffix.chars().all(|c| c.is_ascii_digit()))
            })
        })
        .map(|record| record.id)
        .collect::<Vec<_>>();
    if ids.is_empty() {
        ids.push(resolve_container_id(runtime, service)?);
    }
    ids.sort();
    Ok(ids)
}

#[cfg(target_os = "linux")]
fn current_unix_ms() -> u64 {
    SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis()
        .min(u64::MAX as u128) as u64
}

#[cfg(target_os = "linux")]
fn execute_compose_prerequisite(
    prerequisite: ComposePrerequisite,
    child: &ferro_compose::FanoutChild,
    parent_origin: &RequestOrigin,
    authorization: &SurfaceAuthorization,
    store: &LocalImageStore,
    volume_store: &LocalVolumeStore,
) -> Result<(), String> {
    let (action, resource) = match &prerequisite {
        ComposePrerequisite::ImageBuild(plan) => {
            (AuthorizationAction::ImageBuild, plan.canonical_tag())
        }
        ComposePrerequisite::ImagePull(plan) => {
            (AuthorizationAction::ImagePull, plan.canonical_reference())
        }
        ComposePrerequisite::VolumeCreate(plan) => (AuthorizationAction::VolumeCreate, plan.name()),
    };
    let origin = RequestOrigin::compose_child(
        parent_origin,
        *child.child_id(),
        *child.parent_request_id(),
        *child.idempotency_key(),
        action,
        resource,
        *child.request_digest(),
        child.deadline_unix_ms(),
        child.policy_generation(),
        *child.policy_digest(),
        child.attempt(),
        child.ordinal(),
        *child.plan_digest(),
    );
    match prerequisite {
        ComposePrerequisite::ImageBuild(plan) => {
            let permit = authorization
                .authorize_image_build_plan(&origin, &plan)
                .map_err(|error| error.to_string())?;
            ferro_core::dockerfile_build::execute_dockerfile_build_authorized(plan, store, permit)
                .map(|_| ())
                .map_err(|error| error.to_string())
        }
        ComposePrerequisite::ImagePull(plan) => {
            let permit = authorization
                .authorize_image_fetch_plan(&origin, &plan, 1)
                .map_err(|error| error.to_string())?;
            ferro_core::image_fetch::pull_image_with_store_authorized(
                &runtime_dir(),
                &plan,
                store,
                permit,
            )
            .map(|_| ())
            .map_err(|error| error.to_string())
        }
        ComposePrerequisite::VolumeCreate(plan) => {
            let permit = authorization
                .authorize_volume_create_plan(&origin, &plan)
                .map_err(|error| error.to_string())?;
            volume_store
                .create_with_driver_authorized(plan, permit)
                .map(|_| ())
                .map_err(|error| error.to_string())
        }
    }
}

#[cfg(target_os = "linux")]
fn compose_predecessor_outcome_digest(child: &ferro_compose::FanoutChild) -> [u8; 32] {
    Sha256::digest(
        [
            b"ferrocrate/compose-predecessor-success/v1".as_slice(),
            child.child_id(),
            child.plan_digest(),
            child.request_digest(),
            &child.ordinal().to_be_bytes(),
        ]
        .concat(),
    )
    .into()
}

#[cfg(target_os = "linux")]
fn compose_service_network(
    service: &ComposeService,
    name: &str,
    default_network: &str,
) -> Result<String, String> {
    compose_service_networks(service, name, default_network)?
        .into_iter()
        .next()
        .ok_or_else(|| format!("compose: service {name} has no network attachment"))
}

#[cfg(target_os = "linux")]
fn compose_service_networks(
    service: &ComposeService,
    name: &str,
    default_network: &str,
) -> Result<Vec<String>, String> {
    if service.network_mode.is_some()
        && service
            .networks
            .as_ref()
            .is_some_and(|nets| !nets.is_empty())
    {
        return Err(format!(
            "compose: service {name} cannot combine network_mode with networks"
        ));
    }
    if let Some(mode) = service.network_mode.as_deref() {
        if let Some(target) = mode.strip_prefix("container:") {
            if target.trim().is_empty() {
                return Err(format!(
                    "compose: service {name} has an empty container network target"
                ));
            }
            if target.contains(':') || target.chars().any(char::is_whitespace) {
                return Err(format!(
                    "compose: service {name} has an invalid container network target"
                ));
            }
            return Ok(vec![format!("container:{target}")]);
        }
        return match mode {
            "bridge" | "host" | "none" => Ok(vec![mode.to_string()]),
            other => Err(format!(
                "compose: unsupported network_mode {other} for service {name}"
            )),
        };
    }
    let Some(networks) = service.networks.as_ref() else {
        return Ok(vec![default_network.to_string()]);
    };
    if networks.is_empty() {
        return Ok(vec![default_network.to_string()]);
    }
    let mut resolved = Vec::with_capacity(networks.len());
    for network in networks {
        let network = network.trim();
        let network = if network.is_empty() || network == "default" {
            default_network.to_string()
        } else {
            validate_network_name(network)?;
            network.to_string()
        };
        if !resolved.contains(&network) {
            resolved.push(network);
        }
    }
    Ok(resolved)
}

#[cfg(target_os = "linux")]
#[allow(clippy::too_many_arguments)]
fn connect_compose_secondary_networks(
    runtime: &ContainerRuntime,
    runtime_dir: &Path,
    service: &ComposeService,
    service_name: &str,
    default_network: &str,
    instance: &str,
    origin: &RequestOrigin,
    authorization: &SurfaceAuthorization,
) -> Result<(), String> {
    let networks = compose_service_networks(service, service_name, default_network)?;
    if networks.len() <= 1 {
        return Ok(());
    }
    if !nix::unistd::Uid::effective().is_root() {
        return Err(
            "compose: multiple network attachments require rootful bridge networking".to_string(),
        );
    }
    let id = resolve_container_id(runtime, instance)?;
    for network in networks.into_iter().skip(1) {
        let config = docker_named_endpoint_config(runtime_dir, &network)?;
        let permit = authorization
            .authorize_named(
                origin,
                AuthorizationAction::NetworkAttach,
                ResourceKind::Network,
                &config.network_name,
                config.generation,
            )
            .map_err(|error| error.to_string())?;
        match runtime.connect_network(&id, config) {
            Ok(()) => permit.finish(true).map_err(|error| error.to_string())?,
            Err(error) => {
                if matches!(
                    error,
                    ferro_core::runtime::RuntimeError::PostEffectPersistence(_)
                ) {
                    permit
                        .finish_unknown()
                        .map_err(|finish| finish.to_string())?;
                } else {
                    permit.finish(false).map_err(|finish| finish.to_string())?;
                }
                return Err(error.to_string());
            }
        }
    }
    Ok(())
}

#[cfg(target_os = "linux")]
fn resolve_compose_network_mode(
    runtime: &ContainerRuntime,
    requested: &str,
) -> Result<String, String> {
    let Some(target) = requested.strip_prefix("container:") else {
        return Ok(requested.to_string());
    };
    if let Some(pid) = target.strip_prefix("pid:") {
        let pid = pid
            .parse::<u32>()
            .map_err(|_| "compose: shared rootless network leader PID is invalid".to_string())?;
        if pid == 0 {
            return Err("compose: shared rootless network leader PID must be non-zero".to_string());
        }
        return Ok(format!("container:pid:{pid}"));
    }
    if !nix::unistd::Uid::effective().is_root() {
        return Err(
            "compose: network_mode: container:<service> requires rootful namespace joining; rootless shared networking requires the project supervisor"
                .to_string(),
        );
    }
    let target_id = resolve_container_id(runtime, target)?;
    let target_record = runtime
        .inspect(&target_id)
        .map_err(|error| error.to_string())?;
    if target_record.status != "running" {
        return Err(format!(
            "compose: container network target {target} is not running"
        ));
    }
    let netns = target_record.netns.ok_or_else(|| {
        format!("compose: container network target {target} has no persisted network namespace")
    })?;
    if netns.trim().is_empty() || netns.contains('/') || netns.contains(':') {
        return Err(format!(
            "compose: container network target {target} has an invalid persisted namespace"
        ));
    }
    Ok(format!("container:{netns}"))
}

/// `deploy.resources.limits.memory` in bytes, parsed from Compose size
/// strings (`512M`, `1g`, `64k`).
#[cfg(target_os = "linux")]
fn compose_memory_limit(service: &ComposeService) -> Option<u64> {
    service
        .deploy
        .as_ref()
        .and_then(|deploy| deploy.resources.as_ref())
        .and_then(|resources| resources.limits.as_ref())
        .and_then(|limits| limits.memory.as_deref())
        .and_then(ferro_compose::parse_byte_size)
}

/// `deploy.resources.limits.cpus` as a quota/period pair.
#[cfg(target_os = "linux")]
fn compose_cpu_quota(service: &ComposeService) -> Option<(u64, u64)> {
    service
        .deploy
        .as_ref()
        .and_then(|deploy| deploy.resources.as_ref())
        .and_then(|resources| resources.limits.as_ref())
        .and_then(|limits| limits.cpus.as_deref())
        .and_then(ferro_compose::parse_cpu_limit)
}

#[cfg(target_os = "linux")]
#[allow(clippy::too_many_arguments)]
fn run_compose_service(
    runtime: &ContainerRuntime,
    store: &LocalImageStore,
    volume_store: &LocalVolumeStore,
    project_dir: &Path,
    compose: &ferro_compose::ComposeFile,
    default_network: &str,
    name: &str,
    service: &ComposeService,
    instance_override: Option<&str>,
    prepared_image: Option<&str>,
    network_override: Option<&str>,
    lease_backed_network: bool,
    image_execution: &ResolvedRunImageExecution,
) -> Result<(), String> {
    let image = if let Some(image) = prepared_image {
        image.to_owned()
    } else {
        return Err(format!(
            "compose: service {name} image prerequisite was not prepared"
        ));
    };
    let requested_network = network_override
        .map(str::to_string)
        .unwrap_or(compose_service_network(service, name, default_network)?);
    let requested_network = resolve_compose_network_mode(runtime, &requested_network)?;
    let publish_uses_bridge_network = compose_publish_uses_bridge_network(
        &requested_network,
        lease_backed_network,
    );
    let cmd = compose_service_command(service);
    let env = compose_service_env(project_dir, service)?;
    let labels = compose_service_labels(service);
    let publish = compose_service_ports(service);
    let configured_network_backend =
        std::env::var("FERROCRATE_NETWORK_BACKEND").unwrap_or_else(|_| "ebpf".to_string());
    let bind_mounts = compose_service_mounts(project_dir, volume_store, compose, service)?;
    let restart = service.restart.as_deref().unwrap_or("no");
    let restart = match restart {
        "always" => "always",
        "unless-stopped" => "unless-stopped",
        "no" => "no",
        "on-failure" => "on-failure",
        _ => "no",
    };
    let health = compose_service_health_config(service)?;
    let replicas = if instance_override.is_some() {
        1
    } else {
        service
            .deploy
            .as_ref()
            .and_then(|deploy| deploy.replicas)
            .unwrap_or(1)
    };

    for idx in 1..=replicas {
        let instance_name = if let Some(instance) = instance_override {
            instance.to_owned()
        } else if replicas == 1 {
            name.to_string()
        } else {
            format!("{name}-{idx}")
        };
        handle_run(
            &runtime_dir(),
            runtime,
            store,
            volume_store,
            &image,
            &cmd,
            &requested_network,
            &configured_network_backend,
            &bind_mounts,
            &[],
            &[],
            service.read_only,
            false,
            &env,
            &labels,
            &[],
            &[],
            None,
            image_execution.workdir.as_deref(),
            image_execution.user.as_deref(),
            Some(&instance_name),
            &publish,
            publish_uses_bridge_network,
            None,
            None,
            None,
            None,
            None,
            false,
            health.clone(),
            restart,
            false,
            None,
            None,
            None,
            compose_memory_limit(service),
            compose_cpu_quota(service).map(|(quota, _period)| quota),
            compose_cpu_quota(service).map(|(_quota, period)| period),
            None,
            None,
            None,
            None,
            Some(image_execution),
        )?;
    }
    Ok(())
}

#[cfg(target_os = "linux")]
#[allow(clippy::too_many_arguments)]
fn compose_service_execution_digest(
    runtime: &ContainerRuntime,
    store: &LocalImageStore,
    volume_store: &LocalVolumeStore,
    project_dir: &Path,
    compose: &ferro_compose::ComposeFile,
    default_network: &str,
    name: &str,
    service: &ComposeService,
    instance: &str,
    image: &str,
    network_override: Option<&str>,
    image_execution: &ResolvedRunImageExecution,
) -> Result<(String, [u8; 32]), String> {
    let label_entries = compose_service_labels(service);
    let labels = parse_key_values("label", &label_entries)?;
    let publish = compose_service_ports(service);
    let ports = parse_publish(&publish)?;
    let mut mount_entries = compose_service_mounts(project_dir, volume_store, compose, service)?;
    mount_entries.extend(image_execution.volume_mounts.iter().cloned());
    let mounts = parse_bind_mounts(&mount_entries)?;
    let configured_network_backend = std::env::var("FERROCRATE_NETWORK_BACKEND")
        .unwrap_or_else(|_| "ebpf".to_string())
        .parse::<NetworkBackend>()
        .map_err(|error| error.to_string())?;
    let restart = parse_restart_policy(service.restart.as_deref().unwrap_or("no"))?;
    let requested_network = network_override
        .map(str::to_string)
        .unwrap_or(compose_service_network(service, name, default_network)?);
    let requested_network = resolve_compose_network_mode(runtime, &requested_network)?;
    let network = if is_builtin_network_mode(&requested_network)
        || requested_network.starts_with("managed:")
        || requested_network.starts_with("container:")
    {
        requested_network
    } else {
        "bridge".to_string()
    };
    let (cpu_quota, cpu_period) = match compose_cpu_quota(service) {
        Some((quota, period)) => (Some(quota), Some(period)),
        None => (None, None),
    };
    let compose_limits = build_limits(
        compose_memory_limit(service),
        cpu_quota,
        cpu_period,
        None,
    )?;
    let digest = runtime
        .normalized_run_execution_digest(
            store,
            image,
            &image_execution.command,
            &image_execution.env,
            &labels,
            &HashMap::new(),
            image_execution.health.as_ref(),
            &restart,
            &[],
            compose_limits.as_ref(),
            &mounts,
            &[],
            service.read_only,
            false,
            image_execution.workdir.as_deref(),
            image_execution.user.as_deref(),
            Some(instance),
            &ports,
            &network,
            configured_network_backend,
        )
        .map_err(|error| error.to_string())?;
    Ok((image.to_string(), digest))
}

#[cfg(target_os = "linux")]
fn compose_service_command(service: &ComposeService) -> Vec<String> {
    match service.command.as_ref() {
        Some(ComposeCommandSpec::List(list)) => list.clone(),
        Some(ComposeCommandSpec::String(cmd)) => {
            vec!["sh".to_string(), "-c".to_string(), cmd.clone()]
        }
        None => Vec::new(),
    }
}

#[cfg(target_os = "linux")]
fn compose_service_health_config(
    service: &ComposeService,
) -> Result<Option<ferro_core::container_store::HealthConfig>, String> {
    let Some(health) = service.healthcheck.as_ref() else {
        return Ok(None);
    };
    let test = health
        .test
        .as_deref()
        .ok_or_else(|| "compose: healthcheck.test is required".to_string())?;
    let Some(mode) = test.first().map(String::as_str) else {
        return Err("compose: healthcheck.test must not be empty".to_string());
    };
    let cmd = match mode {
        "NONE" if test.len() == 1 => return Ok(None),
        "CMD" if test.len() > 1 => test[1..].to_vec(),
        "CMD-SHELL" if test.len() > 1 => vec![
            "/bin/sh".to_string(),
            "-c".to_string(),
            test[1..].join(" "),
        ],
        "NONE" => return Err("compose: NONE healthcheck takes no command".to_string()),
        "CMD" | "CMD-SHELL" => {
            return Err(format!("compose: {mode} healthcheck requires a command"));
        }
        other => return Err(format!("compose: unsupported healthcheck mode {other}")),
    };
    Ok(Some(ferro_core::container_store::HealthConfig {
        cmd,
        interval_secs: compose_health_duration(health.interval.as_deref(), 30)?,
        timeout_secs: compose_health_duration(health.timeout.as_deref(), 5)?,
        retries: health.retries.unwrap_or(3),
        start_period_secs: compose_health_duration(health.start_period.as_deref(), 0)?,
    }))
}

#[cfg(target_os = "linux")]
fn compose_health_duration(value: Option<&str>, default: u64) -> Result<u64, String> {
    let Some(value) = value else {
        return Ok(default);
    };
    let split = value
        .find(|ch: char| !ch.is_ascii_digit() && ch != '.')
        .ok_or_else(|| format!("compose: invalid healthcheck duration {value}"))?;
    let amount = value[..split]
        .parse::<f64>()
        .map_err(|_| format!("compose: invalid healthcheck duration {value}"))?;
    let multiplier = match &value[split..] {
        "ns" => 1e-9,
        "us" | "µs" => 1e-6,
        "ms" => 1e-3,
        "s" => 1.0,
        "m" => 60.0,
        "h" => 3600.0,
        _ => return Err(format!("compose: invalid healthcheck duration {value}")),
    };
    if !amount.is_finite() || amount < 0.0 {
        return Err(format!("compose: invalid healthcheck duration {value}"));
    }
    Ok((amount * multiplier).ceil() as u64)
}

#[cfg(target_os = "linux")]
fn compose_service_env(
    project_dir: &Path,
    service: &ComposeService,
) -> Result<Vec<String>, String> {
    let mut env = HashMap::new();
    if let Some(files) = service.env_file.as_ref() {
        for file in files {
            let path = project_dir.join(file);
            let entries = load_env_file_map(&path)?;
            for (key, value) in entries {
                env.insert(key, value);
            }
        }
    }

    match service.environment.as_ref() {
        Some(ComposeEnvironment::Map(map)) => {
            for (key, value) in map {
                env.insert(key.clone(), value.clone());
            }
        }
        Some(ComposeEnvironment::List(list)) => {
            for entry in list {
                if let Some((key, value)) = entry.split_once('=') {
                    env.insert(key.to_string(), value.to_string());
                }
            }
        }
        None => {}
    }

    Ok(env
        .into_iter()
        .map(|(key, value)| format!("{key}={value}"))
        .collect())
}

#[cfg(target_os = "linux")]
fn compose_service_labels(service: &ComposeService) -> Vec<String> {
    match service.labels.as_ref() {
        Some(map) => map
            .iter()
            .map(|(key, value)| format!("{key}={value}"))
            .collect(),
        None => Vec::new(),
    }
}

#[cfg(target_os = "linux")]
fn compose_service_ports(service: &ComposeService) -> Vec<String> {
    let mut out = Vec::new();
    if let Some(ports) = service.ports.as_ref() {
        for entry in ports {
            if entry.contains(':') {
                out.push(entry.clone());
                continue;
            }
            let (port, proto) = entry
                .split_once('/')
                .map(|(port, proto)| (port, Some(proto)))
                .unwrap_or((entry.as_str(), None));
            if let Some(proto) = proto {
                out.push(format!("{port}:{port}/{proto}"));
            } else {
                out.push(format!("{port}:{port}"));
            }
        }
    }
    out
}

#[cfg(target_os = "linux")]
fn compose_service_mounts(
    project_dir: &Path,
    volume_store: &LocalVolumeStore,
    compose: &ferro_compose::ComposeFile,
    service: &ComposeService,
) -> Result<Vec<String>, String> {
    let mut out = Vec::new();
    if let Some(volumes) = service.volumes.as_ref() {
        for entry in volumes {
            let mut parts = entry.split(':');
            let source = parts.next().unwrap_or("");
            let target = parts.next().unwrap_or("");
            if source.is_empty() || target.is_empty() {
                return Err(format!("compose: invalid volume entry {entry}"));
            }
            if source.starts_with('.') || source.contains('/') {
                let resolved = project_dir.join(source).canonicalize().map_err(|error| {
                    format!("compose: bind source {source} cannot be resolved: {error}")
                })?;
                let mode = parts.next().unwrap_or("");
                if mode.is_empty() {
                    out.push(format!("{}:{target}", resolved.display()));
                } else {
                    out.push(format!("{}:{target}:{mode}", resolved.display()));
                }
                continue;
            }
            let (volume_name, _, _) = compose_project_volume_spec(project_dir, compose, source)?;
            let record = volume_store
                .get(&volume_name)
                .map_err(|err| err.to_string())?
                .ok_or_else(|| format!("compose: volume prerequisite was not created: {volume_name}"))?;
            let mode = parts.next().unwrap_or("");
            if mode.is_empty() {
                out.push(format!("{}:{target}", record.path));
            } else {
                out.push(format!("{}:{target}:{mode}", record.path));
            }
        }
    }

    append_compose_file_resource_mounts(
        project_dir,
        compose.secrets.as_ref(),
        service.secrets.as_ref(),
        "/run/secrets",
        "secret",
        &mut out,
    )?;
    append_compose_file_resource_mounts(
        project_dir,
        compose.configs.as_ref(),
        service.configs.as_ref(),
        "/etc/configs",
        "config",
        &mut out,
    )?;
    Ok(out)
}

/// Materialize image-declared anonymous volumes before authorizing the compose
/// child.  Their paths participate in the normalized mount facts, so deferring
/// this to `handle_run` would authorize a different request than we launch.
#[cfg(target_os = "linux")]
fn resolve_compose_image_volume_mounts(
    image_execution: &mut ResolvedRunImageExecution,
    volume_store: &LocalVolumeStore,
    project_dir: &Path,
    compose: &ferro_compose::ComposeFile,
    service: &ComposeService,
    origin: &RequestOrigin,
    authorization: &SurfaceAuthorization,
) -> Result<(), String> {
    if !image_execution.volume_mounts.is_empty() || image_execution.volume_targets.is_empty() {
        return Ok(());
    }
    let explicit_targets = parse_bind_mounts(&compose_service_mounts(
        project_dir,
        volume_store,
        compose,
        service,
    )?)?
    .into_iter()
    .map(|mount| mount.target.to_string_lossy().into_owned())
    .collect::<std::collections::BTreeSet<_>>();
    for target in &image_execution.volume_targets {
        if explicit_targets.contains(target.trim_start_matches('/')) {
            continue;
        }
        let name = anonymous_volume_name();
        let mut driver_opts = BTreeMap::new();
        driver_opts.insert("ferrocrate.anonymous".to_string(), "true".to_string());
        let plan = volume_store
            .prepare_create(&name, "local", driver_opts)
            .map_err(|error| error.to_string())?;
        let permit = authorization
            .authorize_volume_create_plan(origin, &plan)
            .map_err(|error| error.to_string())?;
        let record = volume_store
            .create_with_driver_authorized(plan, permit)
            .map_err(|error| error.to_string())?;
        image_execution
            .volume_mounts
            .push(format!("{}:{target}", record.path));
    }
    Ok(())
}

#[cfg(target_os = "linux")]
fn append_compose_file_resource_mounts(
    project_dir: &Path,
    declarations: Option<&HashMap<String, ferro_compose::FileResource>>,
    references: Option<&Vec<ferro_compose::ServiceFileResource>>,
    default_dir: &str,
    kind: &str,
    mounts: &mut Vec<String>,
) -> Result<(), String> {
    let Some(references) = references else {
        return Ok(());
    };
    let declarations = declarations.ok_or_else(|| {
        format!("compose: service references {kind}s but no top-level {kind} declarations exist")
    })?;
    let project_root = project_dir.canonicalize().map_err(|error| {
        format!("compose: project directory cannot be resolved for {kind} mounts: {error}")
    })?;
    let mut targets = std::collections::HashSet::new();
    for reference in references {
        let source = reference.source();
        let declaration = declarations
            .get(source)
            .ok_or_else(|| format!("compose: service references undeclared {kind} '{source}'"))?;
        if declaration.external || declaration.file.is_none() {
            return Err(format!(
                "compose: external or file-less {kind} '{source}' is unsupported"
            ));
        }
        if reference.unsupported_metadata() {
            return Err(format!(
                "compose: service {kind} '{source}' ownership/mode metadata is unsupported"
            ));
        }
        let relative = declaration.file.as_deref().unwrap_or_default();
        if relative.is_empty() {
            return Err(format!("compose: {kind} '{source}' has an empty file path"));
        }
        let path = project_dir.join(relative).canonicalize().map_err(|error| {
            format!("compose: {kind} '{source}' file cannot be resolved: {error}")
        })?;
        if !path.starts_with(&project_root) {
            return Err(format!(
                "compose: {kind} '{source}' file must stay within the project directory"
            ));
        }
        let metadata = std::fs::metadata(&path).map_err(|error| {
            format!("compose: {kind} '{source}' file cannot be inspected: {error}")
        })?;
        if !metadata.is_file() {
            return Err(format!("compose: {kind} '{source}' file is not regular"));
        }
        let default_target = format!("{default_dir}/{source}");
        let target = reference.target(&default_target);
        if !target.starts_with('/') || target.contains("..") {
            return Err(format!(
                "compose: {kind} '{source}' target must be an absolute safe path"
            ));
        }
        if !targets.insert(target.clone()) {
            return Err(format!("compose: duplicate {kind} target '{target}'"));
        }
        mounts.push(format!("{}:{target}:ro", path.display()));
    }
    Ok(())
}

