/// True for values that only restate a default: null, false, 0, -1, empty
/// strings/arrays/objects, and containers whose members are all
/// default-shaped (covers LogConfig {Type:"",Config:{}} and ConsoleSize
/// [0,0]).
#[cfg(target_os = "linux")]
fn docker_value_is_default_shaped(value: &serde_json::Value) -> bool {
    match value {
        serde_json::Value::Null => true,
        serde_json::Value::Bool(flag) => !flag,
        serde_json::Value::Number(number) => {
            number.as_i64().is_some_and(|v| v == 0 || v == -1)
                || number.as_f64().is_some_and(|v| v == 0.0)
        }
        serde_json::Value::String(text) => text.is_empty(),
        serde_json::Value::Array(items) => items.iter().all(docker_value_is_default_shaped),
        serde_json::Value::Object(map) => map.values().all(docker_value_is_default_shaped),
    }
}

#[cfg(target_os = "linux")]
fn reject_meaningful_host_config_extras(
    extra: &serde_json::Map<String, serde_json::Value>,
) -> Result<(), String> {
    for (field, value) in extra {
        // The daemon has no effect for ContainerIDFile: Docker's CLI writes
        // the cid file itself from the create response.
        if field == "ContainerIDFile" {
            continue;
        }
        // "default" restates NetworkMode's default and appears in other
        // string fields the same way.
        if value.as_str() == Some("default") {
            continue;
        }
        if !docker_value_is_default_shaped(value) {
            return Err(format!(
                "docker: unsupported HostConfig field {field} is set; this runtime does not implement it"
            ));
        }
    }
    Ok(())
}

#[cfg(target_os = "linux")]
fn validate_docker_log_config(config: Option<&DockerLogConfig>) -> Result<(), String> {
    let Some(config) = config else {
        return Ok(());
    };
    let driver = if config.driver.is_empty() { "json-file" } else { &config.driver };
    if driver != "json-file" && config.options.as_ref().is_some_and(|options| !options.is_empty()) {
        return Err(format!("docker: log options are unsupported for log driver {driver}"));
    }
    if driver != "json-file" {
        return Ok(());
    }
    for (key, value) in config.options.as_ref().into_iter().flatten() {
        match key.as_str() {
            "max-size" if parse_docker_log_size(value).is_some() => {}
            "max-file" if value.parse::<u32>().ok().is_some_and(|count| count >= 1) => {}
            "max-size" | "max-file" => {
                return Err(format!("docker: invalid json-file log option {key}={value}"));
            }
            _ => return Err(format!("docker: unsupported json-file log option {key}")),
        }
    }
    Ok(())
}

#[cfg(target_os = "linux")]
fn parse_docker_log_size(value: &str) -> Option<u64> {
    let value = value.trim();
    let split = value.find(|character: char| !character.is_ascii_digit()).unwrap_or(value.len());
    let (number, suffix) = value.split_at(split);
    let multiplier = match suffix.trim().to_ascii_lowercase().as_str() {
        "" | "b" => 1,
        "k" | "kb" | "kib" => 1024,
        "m" | "mb" | "mib" => 1024 * 1024,
        "g" | "gb" | "gib" => 1024 * 1024 * 1024,
        _ => return None,
    };
    number.parse::<u64>().ok()?.checked_mul(multiplier).filter(|size| *size > 0)
}

