#[cfg(target_os = "linux")]
impl DockerCreateSpec {
    fn effective_network_attachments(&self) -> Vec<String> {
        self.network_attachments
            .clone()
            .unwrap_or_else(|| vec![self.network_mode.clone()])
    }

    fn start_network_mode(&self) -> &str {
        if self
            .effective_network_attachments()
            .iter()
            .any(|network| network == &self.network_mode)
        {
            &self.network_mode
        } else {
            "none"
        }
    }
}

#[cfg(target_os = "linux")]
struct DockerStartRunInputs {
    path_binds: Vec<String>,
    volume_binds: Vec<String>,
    annotations: Vec<String>,
}

#[cfg(target_os = "linux")]
fn docker_start_run_inputs(spec: &DockerCreateSpec) -> DockerStartRunInputs {
    // Docker's Binds mixes host-path binds (absolute source) with named
    // volumes. Keep each handle_run argument explicit here: these adjacent
    // string slices are otherwise easy to transpose without a type error.
    let (mut path_binds, mut volume_binds): (Vec<String>, Vec<String>) = spec
        .binds
        .iter()
        .cloned()
        .partition(|entry| entry.starts_with('/'));
    if spec.ipc_mode_host {
        path_binds.push("/dev/shm:/dev/shm".to_string());
    }
    volume_binds.extend(spec.image_volumes.iter().cloned());

    let mut annotations = spec
        .log_options
        .iter()
        .map(|(key, value)| format!("io.ferrocrate.log.{key}={value}"))
        .collect::<Vec<_>>();
    annotations.sort();
    annotations.push(format!(
        "io.ferrocrate.log.driver={}",
        spec.log_driver
    ));
    if spec.ipc_mode_host {
        annotations.push("io.ferrocrate.ipc.mode=host".to_string());
    }
    if !spec.network_aliases.is_empty() {
        annotations.push(format!(
            "io.ferrocrate.network.aliases={}",
            spec.network_aliases.join(",")
        ));
    }

    DockerStartRunInputs {
        path_binds,
        volume_binds,
        annotations,
    }
}

#[cfg(target_os = "linux")]
fn default_log_driver() -> String {
    "json-file".to_string()
}

#[cfg(target_os = "linux")]
fn docker_pending_id(
    pending: &std::collections::HashMap<String, DockerCreateSpec>,
    requested: &str,
) -> Option<String> {
    if pending.contains_key(requested) {
        return Some(requested.to_string());
    }
    let matches = pending
        .iter()
        .filter(|(id, spec)| id.starts_with(requested) || spec.name.as_deref() == Some(requested))
        .map(|(id, _)| id.clone())
        .collect::<Vec<_>>();
    (matches.len() == 1).then(|| matches.into_iter().next().expect("one pending match"))
}

#[cfg(target_os = "linux")]
fn docker_resolve_id(
    runtime: &ContainerRuntime,
    pending: &std::collections::HashMap<String, DockerCreateSpec>,
    requested: &str,
) -> Result<String, String> {
    if runtime.inspect(requested).is_ok() {
        return Ok(requested.to_string());
    }
    if let Ok(id) = resolve_container_id(runtime, requested) {
        return Ok(id);
    }
    docker_pending_id(pending, requested)
        .ok_or_else(|| format!("docker: container not found: {requested}"))
}

