#[cfg(target_os = "linux")]
fn validate_docker_exec_command(cmd: &[String]) -> Result<(), String> {
    if cmd.is_empty() || cmd.iter().any(|arg| arg.is_empty()) {
        return Err("docker: exec Cmd must contain at least one non-empty argument".to_string());
    }
    Ok(())
}

#[cfg(target_os = "linux")]
fn validate_docker_exec_start(tty: bool) -> Result<(), String> {
    // Rootful TTY exec is backed by a kernel PTY. Rootless requests are
    // rejected by the runtime with a precise unsupported-host diagnostic.
    let _ = tty;
    Ok(())
}

#[cfg(target_os = "linux")]
fn validate_docker_exec_create(tty: bool) -> Result<(), String> {
    // The TTY preference is retained by the Docker client and applied at
    // start; the rootful runtime allocates the PTY there.
    let _ = tty;
    Ok(())
}

