#[allow(dead_code)] // Consumed by the version-2 build route in delivery step 3.
enum BuildkitSessionCommand {
    ReceiveLocal {
        name: String,
        destination: PathBuf,
        reply: tokio::sync::oneshot::Sender<Result<(), String>>,
    },
    Credentials {
        host: String,
        reply: tokio::sync::oneshot::Sender<Result<Option<RegistryAuth>, String>>,
    },
}

#[cfg(target_os = "linux")]
#[allow(dead_code)] // Consumed by the version-2 build route in delivery step 3.
async fn receive_buildkit_session_local(
    state: &DockerCompatState,
    uuid: &str,
    name: &str,
    destination: &Path,
    timeout: Duration,
) -> Result<(), String> {
    let deadline = Instant::now() + timeout;
    let session = loop {
        let session = state
            .buildkit_sessions
            .lock()
            .map_err(|error| format!("buildkit session registry poisoned: {error}"))?
            .get(uuid)
            .cloned();
        if let Some(session) = session {
            break session;
        }
        let remaining = deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            return Err(format!("buildkit session: unknown or expired session {uuid}"));
        }
        tokio::time::sleep(remaining.min(Duration::from_millis(10))).await;
    };
    if !session.methods.contains("/moby.filesync.v1.FileSync/DiffCopy") {
        return Err("buildkit session: FileSync.DiffCopy was not exposed".to_string());
    }
    let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
    session
        .commands
        .send(BuildkitSessionCommand::ReceiveLocal {
            name: name.to_string(),
            destination: destination.to_path_buf(),
            reply: reply_tx,
        })
        .await
        .map_err(|_| "buildkit session: session disconnected".to_string())?;
    tokio::time::timeout(deadline.saturating_duration_since(Instant::now()), reply_rx)
        .await
        .map_err(|_| "buildkit session: filesync timed out".to_string())?
        .map_err(|_| "buildkit session: session disconnected".to_string())?
}

#[cfg(target_os = "linux")]
async fn receive_buildkit_session_credentials(
    state: &DockerCompatState,
    uuid: &str,
    host: &str,
    timeout: Duration,
) -> Result<Option<RegistryAuth>, String> {
    let deadline = Instant::now() + timeout;
    let session = loop {
        let session = state
            .buildkit_sessions
            .lock()
            .map_err(|error| format!("buildkit session registry poisoned: {error}"))?
            .get(uuid)
            .cloned();
        if let Some(session) = session {
            break session;
        }
        let remaining = deadline.saturating_duration_since(Instant::now());
        if remaining.is_zero() {
            return Err(format!("buildkit session: unknown or expired session {uuid}"));
        }
        tokio::time::sleep(remaining.min(Duration::from_millis(10))).await;
    };
    if !session
        .methods
        .contains("/moby.session.auth.v1.Auth/Credentials")
    {
        return Ok(None);
    }
    let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
    session
        .commands
        .send(BuildkitSessionCommand::Credentials {
            host: host.to_string(),
            reply: reply_tx,
        })
        .await
        .map_err(|_| "buildkit session: session disconnected".to_string())?;
    tokio::time::timeout(deadline.saturating_duration_since(Instant::now()), reply_rx)
        .await
        .map_err(|_| "buildkit session: credentials timed out".to_string())?
        .map_err(|_| "buildkit session: session disconnected".to_string())?
}

#[derive(Default)]
struct DockerAttachReadiness {
    ready: Mutex<bool>,
    condition: Condvar,
}

#[cfg(target_os = "linux")]
impl DockerAttachReadiness {
    fn mark_ready(&self) {
        if let Ok(mut ready) = self.ready.lock() {
            *ready = true;
            self.condition.notify_all();
        }
    }

    fn wait(&self, timeout: Duration) -> bool {
        let Ok(ready) = self.ready.lock() else {
            return false;
        };
        self.condition
            .wait_timeout_while(ready, timeout, |ready| !*ready)
            .map(|(ready, _)| *ready)
            .unwrap_or(false)
    }
}

#[cfg(target_os = "linux")]
fn prune_live_attach_registrations(
    registrations: &mut Vec<Weak<DockerAttachReadiness>>,
) -> Vec<Arc<DockerAttachReadiness>> {
    registrations.retain(|entry| entry.strong_count() > 0);
    registrations.iter().filter_map(Weak::upgrade).collect()
}

#[cfg(target_os = "linux")]
struct DockerCompatState {
    next_id: AtomicU64,
    /// The daemon owns a single container-store connection, but compatibility
    /// requests also touch name reservations and lifecycle state through
    /// independent helpers.  Queue those short request transactions here so
    /// concurrent Compose requests never expose a transient store lock to the
    /// client.
    container_store_operations: Mutex<()>,
    /// Docker Compose submits independent network requests concurrently.  A
    /// network lifecycle is a read-modify-write transaction over the durable
    /// network store, so serialize it for the daemon rather than letting two
    /// successful creates overwrite each other's publication.
    network_operations: Mutex<()>,
    pending: Mutex<HashMap<String, DockerCreateSpec>>,
    starting: Mutex<std::collections::HashSet<String>>,
    attach_readiness: Mutex<HashMap<String, Vec<Weak<DockerAttachReadiness>>>>,
    pending_path: PathBuf,
    pending_snapshot_hook: Arc<dyn PendingSnapshotPublicationHook>,
    name_store: ferro_core::sqlite_container_store::SqliteContainerStore,
    execs: Mutex<HashMap<String, DockerExecSpec>>,
    auto_remove_results: Mutex<HashMap<String, Option<i32>>>,
    events: Mutex<DockerEventStore>,
    buildkit_sessions: Mutex<HashMap<String, BuildkitSessionHandle>>,
    buildkit_builds: Mutex<HashMap<String, Arc<BuildkitBuild>>>,
    buildkit_build_registered: tokio::sync::Notify,
}

