    #[test]
    fn volume_handlers_run() {
        let temp = tempfile::tempdir().expect("tempdir");
        let runtime_dir = temp.path().to_path_buf();
        let authorization = test_surface_authorization(&runtime_dir);

        handle_volume(
            &runtime_dir,
            VolumeCommands::Create {
                name: "data".to_string(),
                driver: "local".to_string(),
                opts: Vec::new(),
            },
            &authorization,
        )
        .expect("create volume");
        let store = ferro_core::volume_store::LocalVolumeStore::open(runtime_dir.join("volumes"))
            .expect("store");
        let record = store.get("data").expect("get").expect("record");
        std::fs::write(
            std::path::PathBuf::from(&record.path).join("hello.txt"),
            "hi",
        )
        .expect("write");
        drop(store);

        let archive = runtime_dir.join("backup.tar");
        handle_volume(
            &runtime_dir,
            VolumeCommands::Backup {
                name: "data".to_string(),
                path: archive.display().to_string(),
            },
            &authorization,
        )
        .expect("backup volume");

        handle_volume(
            &runtime_dir,
            VolumeCommands::Rm {
                name: "data".to_string(),
            },
            &authorization,
        )
        .expect("rm volume");

        handle_volume(
            &runtime_dir,
            VolumeCommands::Restore {
                name: "data".to_string(),
                path: archive.display().to_string(),
            },
            &authorization,
        )
        .expect("restore volume");
        handle_volume(
            &runtime_dir,
            VolumeCommands::Ls {
                filters: vec![],
                quiet: false,
                format: "text".to_string(),
            },
            &authorization,
        )
        .expect("ls volumes");
        handle_volume(
            &runtime_dir,
            VolumeCommands::Inspect {
                name: "data".to_string(),
                format: "json".to_string(),
            },
            &authorization,
        )
        .expect("inspect volume");
        handle_volume(
            &runtime_dir,
            VolumeCommands::Rm {
                name: "data".to_string(),
            },
            &authorization,
        )
        .expect("rm volume");
    }

