    struct TestRuntimeDir {
        original: Option<String>,
        _dir: tempfile::TempDir,
        _guard: std::sync::MutexGuard<'static, ()>,
    }

    impl TestRuntimeDir {
        fn new() -> Self {
            let guard = ENV_MUTEX
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            let dir = tempfile::tempdir().expect("tempdir");
            let original = std::env::var("FERROCRATE_HOME").ok();
            unsafe {
                std::env::set_var("FERROCRATE_HOME", dir.path());
            }
            Self {
                original,
                _dir: dir,
                _guard: guard,
            }
        }
    }

    impl Drop for TestRuntimeDir {
        fn drop(&mut self) {
            if let Some(value) = &self.original {
                unsafe {
                    std::env::set_var("FERROCRATE_HOME", value);
                }
            } else {
                unsafe {
                    std::env::remove_var("FERROCRATE_HOME");
                }
            }
        }
    }

